WoWFQ[86836] = { t = "شکارچی در انتظار است", d = "به Orweyna از خطرها و دیوانگی‌ای که در Rift of Aln کمین کرده هشدار داده‌ام، اما او باور دارد تنها راه پیش‌رویش همین است. به ایمانش رشک می‌برم.\n\nکسی هست که بتواند راه را به او بنمایاند: Shul'ka. شکارچیان سایه‌ها. آن‌ها همه‌چیز را قربانی کرده‌اند تا مردم haranir را از اثرهای rift در امان نگه دارند.\n\nبه یکی‌شان خبر می‌دهم که به کمک نیاز داری. او را در Vale of Mists پیدا می‌کنی.", o = { "از Orweyna دربارهٔ Shul'ka بپرس", "Orweyna را در Shrine of Mists پیدا کن" }, c = "پیوندم با Goddess را برای محافظت از مردمم در برابر خطرهای Rift of Aln قطع کرده‌ام. باور ندارم کسی بدون دانستن ریسکش باید به آنجا قدم بگذارد. haranir بدون حفاظت، تسلیم مرگ می‌شوند." }
WoWFQ[86851] = { t = "بنیان Aln", d = "حضور Goddess در همه‌چیزِ Rift of Aln طنین می‌اندازد. صدا برای مردمان haranir بیش از حد قدرتمند است که در برابرش بایستند. در چند دقیقه، یکی از گلّه‌مان برای همیشه گم می‌شود.\n\nاما راه‌هایی هست که برای مدتی کوتاه خود را حفظ کنی. بی‌اعتبارانی را که از rift بالا می‌خزند بکش و Alndust‌ای را جمع کن که از آن آفریده شده‌اند. می‌توانم به Orweyna نشان دهم چطور راه‌حلی کوتاه‌مدت برای ورود به rift بسازد.", o = { "Alndust تحلیل‌رفته" }, p = "به همراه جوانت می‌گویم با Alndust چه باید بکند.", c = "دستانم هر جا Alndust به‌شان می‌رسد سوز‌سوز می‌شوند. حسی غریب... و ناخوشایند هم نیست.\n\nShul'ka ارجمند به من آموخت چطور alndust را به کار اندازم تا haranir را در Rift در امان نگه دارد. سخت به نظر می‌رسید، اما با این جادویی که در من موج می‌زند، حس می‌کنم از عهده‌اش برمی‌آیم." }
WoWFQ[86855] = { t = "پیامد وظیفه‌مان", d = "باید با چشم خودت ببینی که Rift of Aln با هر haranir چه می‌کند. حتی آن‌ها که مرزبان مرزند هم اغلب از ندایش اثر می‌پذیرند.\n\nاین را بگیر. از آن به‌عنوان مرهم اضطراری برای یاری زخمیانِ خطرهای Aln استفاده می‌کنم. در این سرزمین‌ها گشت بزن و به هر که نیاز دارد مدد برسان. شاید آن‌وقت بفهمی آنچه می‌خواهی بکنی چقدر سنگین است.", o = { "یاری به مدافع زخمی", "Salve of Aln (provided)" }, p = "نمی‌دانستم این دورافتاده‌های rift می‌توانند این‌قدر ما را اثر بگذارند...", c = "دیدن اثر Rift بر مردمم آدم را به خودش می‌آورد. اما دخالت Amarakk ناخواسته امیدی در من زده است.\n\nباید برای یافتن جواب Hagar به درون Rift بروم، و با کمک Shul'ka شاید حتی از این آزمون جان به در ببرم." }
WoWFQ[86856] = { t = "خفه کردن ندا", d = "Amarakk به من آموخت چطور alndust را برای ساخت مرهم آماده کنم. در دوزهای کم. Alndust ذهن را در برابر دیوانگی و وحشت محکم می‌کند. روشنی و آرامش می‌بخشد، اما فقط اگر استادانه به کار رود.\n\nکمکت می‌کند لنگری برای اینجا بگذارم، <name>. آیین ظریف است و شکستش می‌تواند فاجعه باشد.", o = { "قرار دادن Alndust" }, p = "فرایند ساده به نظر می‌رسید--به‌خوبی در توان من. اما از حضورت اینجا که زمین‌گیرم کند ممنونم.", c = "صدای Goddess را نمی‌شنوم.\n\nمتنفرم ازش.\n\nAmarakk چطور این‌طور زندگی می‌کند؟" }
WoWFQ[86857] = { t = "فرورفتن در Rift", d = "با این، می‌توانم به درون Rift of Aln سر بزنم. وقت زیاد ندارم، پس نباید درنگ کنیم.\n\nبیایید Amarakk را پیدا کنیم و کمکش را جلب کنیم.", o = { "دنبال Wardهای Shul'ka بگرد" }, c = "آن تجلی یکی از خالص‌ترین شکل‌های دیوانگی Aln است که اینجا خانه دارد. Ward من فقط مدتی حواسش را پرت می‌کند. باید تند پیش برویم." }
WoWFQ[86858] = { t = "دیوانگی تا ریشه رفته", d = "وسط یکی از وظایفم پیدایت کردم. کسی زمان زیادی در Rift گذشته و طعمهٔ ندای Goddess شده است. باید نجاتش دهم و به جایی که مالش است پس بفرستم.\n\nدر این کار کمکم کن، تا من هم کمکت کنم.", o = { "مهار شدن On'hiea" }, p = "می‌توانیم نجاتش دهیم!", c = "یک روح دیگر نجات یافت.\n\nمن برای همین این کار را می‌کنم، <name>. همهٔ فدیه‌هایم، بستن گوشم به صدای Goddess، برای هر روحی که از چنگ Rift می‌رانم می‌ارزد." }
WoWFQ[86859] = { t = "به سختی، راهی", d = "از لحظه‌ای که Orweyna از جوابی حرف زد، دارم فکر می‌کنم منظور Hagar چه می‌توانست باشد. نه چشمهٔ جادویی‌ای در کار است، نه سلاح. همه‌چیز در rift از یک منبع آفریده شده: Alndust، تقطیرِ نفوذ Goddess. اگر تجلی بزرگی را شکار کنیم، قدرت آفرینش را در خالص‌ترین شکلش خواهی داشت.\n\nبدون کمک نمی‌توانیم از پس‌اش برآییم. Rift را بگرد و قارچ‌هایی به‌قدر کافی بزرگ برای کشت پیدا کن. می‌توانم با آن‌ها برتری‌ای به دست‌مان بدهم.", o = { "قارچ Alngrown", "در عمق بیشترِ Rift of Aln با Amarakk دیدار کن." }, p = "هر برتری‌ای که در برابر تجلی به دست بیاوریم، شانس زنده ماندن‌مان را بالا می‌برد.", c = "شاید با این شانسی داشته باشیم. می‌توانم سلاح‌هایم را به آن آغشته کنم و زهری نیرومند بسازم." }
WoWFQ[86860] = { t = "قبل از آنکه بزرگ شوند", d = "در هر جانداری که در Rift of Aln می‌گردد، انبوهی از بنیانِ نفوذ Goddess طنین‌انداز است. این Alndust شوق دارد با همان‌نوع‌هایش یکی شود. بخشی از وظایف من به‌عنوان Shul'ka این است که شمار تجلی‌های بزرگ را کم نگه دارم تا بر Den چیره نشوند.\n\nساده‌ترین وقتِ این کار، وقتی است که هنوز کوچک‌اند.\n\nاین نیزه را بگیر. می‌توانی با آن جانداران کوچک‌تر را تا اندازه‌های... بی‌اهمیت خرد کنی.", o = { "استفاده از نفوذ Amarakk روی جاندار Rift", "شکست دادن دشمنان alnscorned در Rift of Aln", "در عمق بیشترِ Rift of Aln با Amarakk دیدار کن." }, p = "امیدوارم همین کافی باشد.", c = "خوب بود." }
WoWFQ[86861] = { t = "گله‌کردن تجلی‌ها", d = "در آستانهٔ جنگ با تجلی‌ای عظیم هستیم. بگذار دوباره تأکید کنم: فقط باید با یکی بجنگیم.\n\nاگر دو تا با هم بیایند، شانسی برای زنده ماندن نداریم. این Wardها را دورتادور Rift بگذار تا بقیه را از ما دور کند. طولانی دوام نمی‌آورند... اما به هر برتری‌ای که بشود رسید نیاز داریم.", o = { "قرار دادن Wardها", "در عمق بیشترِ Rift of Aln با Amarakk دیدار کن." }, p = "این wardها آفریدهٔ دست خودم‌اند. با تقلید واکنش آن موجودات به غذا، موجودات بزرگ‌تر را به سمت خود می‌کشانند.", c = "این باید کافی باشد." }
WoWFQ[86862] = { t = "هرچه بزرگ‌تر، Aln‌تر", d = "فقط یک شانس داریم.\n\nدعا می‌کنم به‌قدر کافی آماده باشیم.", o = { "کشته شدن تجلی طعمه‌شده", "جمع‌آوری Greater Alndust", "Greater Alndust" }, p = "قدرت Rift of Aln فراتر از فهم فانی‌هاست. کاری که می‌کنیم فقط قرض گرفتن اندکی از آن برای لحظه‌ای کوتاه است.", c = "فکر می‌کردم هرگز با چشم خودم این را نبینم... و حالا اینجاییم.\n\nبگذار این ماجرا ارزشش را داشته باشد." }
WoWFQ[86864] = { t = "نگهبانی از Den", d = "بالاخره لحظه‌ای برای نفس کشیدن پیدا شد. اینجا به Goddess نزدیک‌تریم--زیر Cradle هستیم، همان‌جا که روزگاری می‌آسود.\n\nبزرگان اجازه نمی‌دهند از Alndust‌ای که قرن‌ها جمع کرده‌اند ذره‌ای خرج کنیم. فقط آنچه Goddess قبل‌ها از ما خواسته را می‌بینند، نه آنچه دنیایش الان نیاز دارد.\n\nAlndust کمیاب است، اما راه‌هایی برای پیدا کردنش هست. بپرس و بگرد. من هم... جای دیگری را بررسی می‌کنم.", o = { "با Innkeeper صحبت کن", "با Quartermaster صحبت کن", "با Flight Master صحبت کن", "با Ku'paal صحبت کن", "در لبهٔ Den به Orweyna بپیوند." }, p = "امیدوارم اینجا بتوانی کمی استراحت کنی. باید یاد بگیری در این مکان راه بیایی.", c = "در آخر، باید خودمان راهش را پیدا کنیم." }
WoWFQ[86865] = { t = "به جست‌وجوی مشکل", d = "کاری که Hagar خواسته بود را انجام دادیم. قدم بعدی آزمودن این است روی چیزی--یا کسی--که به Lightbloom آلوده است.\n\nشاید در Harandar سخت باشد Lightbloom را به‌قدر کافی پیدا کرد، اما به باورم در Har'alnor هر چه لازم داریم پیدا می‌شود. آنجا به تو می‌پیوندم!", o = { "در Har'alnor به Orweyna بپیوند." }, c = "خانه‌های‌مان را رها کردیم. برمی‌گردیم." }
WoWFQ[86866] = { t = "می‌توان این را درمان کرد؟", d = "rutaaniها از روستاهای نزدیک به Har'alnor گریخته‌اند. نگهبان‌ها به من گفتند بعضی‌شان به Lightbloom آلوده شده‌اند، اما هنوز تسلیم اثرهایش نشده‌اند.\n\nاین شاید بهترین فرصت‌مان برای آزمودن قدرت Alndust باشد. وقت طلایی است!", o = { "کمی بمان و به Hannan گوش بده", "استفاده از Alndust روی Rutaani آلوده" }, p = "همین است، <name>. لحظهٔ حقیقت. جوابی برای مشکلات Azeroth داریم؟", c = "شاید alndust نتواند کسی را که به‌کلی به lightbloom افتاده بازیابد، اما باید بتواند بقیه را در برابر آلودگی بیشتر واکسنه کند.\n\nهمین باید کافی باشد." }
WoWFQ[86867] = { t = "به دل Lightbloom", d = "haranirهای در دسترس را جمع کردیم و Alndust را پخش کردیم. هر چه لازم داریم در اختیار داریم، اما باید بتوانند بی‌خطر وارد منطقه شوند. پیشاهنگ‌ها گفتند جاندارانی که Lightbloom را می‌پراکنند سپری دارند. باید جلویشان را بگیریم. شمارشان هم باید کم کنیم.\n\nسوار petalwing شو، <name>، و راه را باز کنیم.", o = { "سوار شدن بر Haranir Petalwing", "نابودی سپر Lightbloom Spreader", "شکست دادن rutaaniهای Lightbloom" }, p = "با هم می‌تازیم!", c = "حالا می‌توانیم شروع کنیم." }
WoWFQ[86874] = { t = "درو کردن Light", o = { "Lightbloom مهار شد", "Kill Credit: T1 [DNT] slain (34)", "Kill Credit: T2 [DNT] slain (20)", "Kill Credit: T3 [DNT] slain (25)" }, c = "هرچند Lightbloom هرجا که ریشه دوانده سرسبز مانده، به نظر می‌رسد یورش‌های کمک‌گرفته از Alndust در محدود کردن رشد و گسترش بیشتر کارسازند. برای حالا، بقیهٔ Harandar باید از گسترش بیشتر در امان باشد." }
WoWFQ[86877] = { t = "هرسِ به‌جا", d = "این تهدیدی است که اگر مهار نشود می‌تواند همهٔ Harandar را نابود کند. برای همین باید از ریشه بکنیمش.\n\nruutaniهایی که فرصت فرار از اینجا را نداشتند، حالا به‌کلی آلوده شده‌اند. بد است، اما نقشهٔ حمله‌مان را ساده می‌کند. رهبرانشان باید دارند Lightbloom را می‌پراکنند. باید سرنگون‌شان کنیم.", o = { "کشته شدن Lightblinded Sap Weaver", "Orweyna را در Blinding Bloom پیدا کن." }, p = "اگر بگذاریم این رهبران نیرو بگیرند، نیروی بیشتری به Lightbloom می‌کشانند. نمی‌توانیم بگذاریم این شود.", c = "کاش می‌شد همه را نجات داد، اما...\n\nکاری هولناک اما ضروری." }
WoWFQ[86880] = { t = "عزیزانمان، بازگشته", d = "haranirها پای ریشه‌های Shaladrassil حضور داشتند، به نشانهٔ حسن نیت با فرهنگ‌هایی که در خانهٔ ما زندگی می‌کنند. وقتی نگهبانان عقب‌نشینی کردند، بعضی از یادگارهای عزیز و آثارمان را جا گذاشتند.\n\nبا این گسترش Lightbloom که از هر تصورم فراتر رفت، نمی‌دانم کِی می‌توانیم برگردیم. بیایید آن آثار را در Blinding Bloom پیدا کنیم و به خانه بیاوریم.", o = { "بازیابی آثار تاریخی", "Orweyna را در Blinding Bloom پیدا کن." }, p = "خوب می‌شود این وسایل را به دست‌های خودمان برگردانیم.", c = "این آثار در برابر جان کسانی که اینجا گرفتار شدند هیچ‌اند... اما خوشحالم که برگشتند." }
WoWFQ[86881] = { t = "از ریشه", d = "رشد‌هایی که به آن‌ها امکان می‌دهند Lightbloom را این‌قدر تند بپراکنند، بعد از حملهٔ هوایی تو آسیب‌پذیرند، اما هنوز باید نابودشان کنیم. به Blinding Bloom برگرد و پیش از آنکه از حملهٔ ما جان بگیرند، پخش‌کننده‌ها را از ریشه درآور.", o = { "نابودی Lightbloom Spreader", "Orweyna را در Blinding Bloom پیدا کن." }, p = "باید جلوی گسترش Lightbloom را بگیریم، وگرنه همهٔ Harandar را می‌بلعد.", c = "دعا می‌کنم این به کار همه‌مان بیاید." }
WoWFQ[86882] = { t = "Alndust در دستان درست", d = "حالا می‌توانیم به ریشه‌های Shaladrassil برویم و جلوی گسترش بیشتر Lightbloom در Harandar را بگیریم.\n\nAlndust به‌قدر کافی داریم تا هر یک از haranirها را که حاضر است جانش را به خطر بیندازد و به نبردمان بیاید واکسنه کنیم. پیدایشان کن، <name>، و Alndust را به‌شان بده.", o = { "واکسینه شدن haranirها", "در Blinding Bloom با Hannan صحبت کن" }, p = "می‌دانم مردمم آماده‌اند که به میدان بیایند.", c = "این خیلی بیشتر از حرف‌های Rootwarden بود. Lightbloom چطور این‌قدر و این‌قدر تند پخش شده؟" }
WoWFQ[86890] = { t = "به مردم بگو چه دیدی", d = "شاید جلوی این رشد بدخیم را گرفتیم، اما سؤال‌های‌مان خیلی بیشتر از جواب‌هاست. چطور این اتفاق افتاد؟ چطور این‌قدر رشد کرد؟ مگر Ruia چطور وسعت این فاجعه را نفهمید؟\n\n<name>، باید همین حالا به Cradle برگردیم. بزرگان باید بدانند امروز چه گذشت.", o = { "بازگشت به Den", "خطاب به شورا" }, p = "دعا می‌کنم این بار حقیقت را راحت‌تر بپذیرند.", c = "Azeroth به کمک ما نیاز دارد. نمی‌توانم دست روی دست بگذارم و ببینم زیر بار می‌رود.\n\nمی‌دانم تو هم نمی‌گذاری." }
WoWFQ[86900] = { t = "به سوی Har'athir", d = "همهٔ ریشه‌های این دنیا به سوی میهن‌مان رشد می‌کنند. ریشه‌هایی که بالای سرت‌اند عظیم‌اند، اما تازه--زادهٔ World Tree نوپایی که تو و هم‌نوعانت Amirdrassil می‌نامید.\n\nبه قیاس World Treeها، عجیب است. اما سرشتش به اندازهٔ گستره‌اش مهم نیست. هر ریشه‌ای که بخواهد از دنیای ما محافظت کند، لایق محافظت است.\n\nبیایید از راه به پایین، به سوی Har'athir برویم و حال Rootwarden را بپرسیم. می‌پرسیم آیا هنوز نشانه‌ای از Lightbloom دیده یا نه.", o = { "دنبال Orweyna برو", "با Ku'paal صحبت کن", "با Oorla صحبت کن", "با Danul صحبت کن", "با Orweyna صحبت کن", "حال Halduron را بپرس", "دنبال Orweyna به Har'athir برو." }, c = "غریبه‌ها حق ورود به Harandar ندارند. Orweyna مقدس‌ترین قانون ما را شکست.\n\nاینجا خوش آمدی نداری، غریبه." }
WoWFQ[86901] = { t = "Rift و Den", d = "همان‌طور که حدس می‌زدم، بزرگان از رفتارم بسیار دلخورند. حالا که بچه‌ها و Ku'paal را به امنیت رساندم، آماده‌ام رو در روی شورا بایستم.\n\nهر کاری از دستم بربیاید می‌کنم تا بفهمند Lightbloom تهدید است، و تا توان حرکت آزاد تو در Harandar را فراهم کنم.\n\nPetalvane تو را سالم به Den می‌رساند. تند کنیم.", o = { "سوار شدن بر Petalvane", "دنبال Orweyna به Den برو" }, c = "با احتیاط قدم بردار، <name>. haranirها نیرویی قابل احترام‌اند و از آمدن ما به‌شدت بیدار و مراقب‌اند.\n\nشورا تشکیل جلسه داده و آماده است به حرف‌های Orweyna گوش دهد. امیدوارم بتواند قانعشان کند که Lightbloom تهدید است و به کمک ما نیاز دارند." }
WoWFQ[86909] = { t = "روح‌های بی‌قرار", o = { "Restless Spirit رانده شد (4)", "Swirling Darkness کشته شد (8)" } }
WoWFQ[86910] = { t = "لگدکوبی Koozat", d = "Koozat معمولاً خیلی آرام و ملایم است. این اصلاً شبیه خودش نیست. لطفاً برو ببین چه اتفاقی افتاده.", o = { "دنبال Orweyna برو." }, p = "Koozat معمولاً جانوری پرخاشگر نیست.", c = "Koozat فعلاً کوچک‌ترین دغدغهٔ ماست. lightbloom رسیده است. Har'mara زیر حمله است!" }
WoWFQ[86911] = { t = "پژواک‌ها و خاطره‌ها", d = "تاریخچهٔ haranirها ده‌ها هزار سال است که در غارهای درون ثبت می‌شود. خاطرات مردم‌مان روی سنگ نقاشی شده، تا هرگز فراموش نکنیم از کجا آمده‌ایم و وظیفه‌مان چیست.\n\nتو اولین غریبه‌ای است که تا حالا Den of Echoes را از نزدیک دیده. وقتی به نقاشی‌ها دست بزنی، اجدادمان قصه‌ها و رنج‌هایشان را با تو قسمت می‌کنند.\n\nZur'ashar Kassameh درون منتظرت است. او تو و Halduron را در این سفرها راهنمایی می‌کند. بخت با‌ت.", o = { "با Hagar صحبت کن", "با Zur'ashar Kassameh صحبت کن", "فعال کردن Visionstone", "جمع‌آوری Iceberryها" }, p = "مردم‌مان ده‌ها هزار سال است اینجا هستند، اما همیشه این‌طور نبود. روزگاری، مثل تو، روی سطح زندگی می‌کردیم.", c = "از نخستین آزمون عبور کردی، اما آزمون واقعی هنوز در راه است." }
WoWFQ[86912] = { t = "در مسیر ریشه‌ها", d = "نگاهی به تاریخچه‌مان انداختی. یک آزمون دیگر باقی مانده است.\n\nاگر جان سالم به در ببری، برکت Goddess بر تو خواهد بود و شورا دیگر نمی‌تواند حضورت را اینجا انکار کند.\n\nحالا به دل زمین فرو برو و در ردپای اجدادمان قدم بگذار.", o = { "کنار Gulf of Memories با Hagar صحبت کن", "ورود به Gulf of Memory", "Fragment of Revelation", "با Orweyna صحبت کن" }, p = "از Gulf of Memories جان سالم به در بردی. به Har'mara خوش آمدی، دوست من.", c = "بیدار شدی. خوب. حالا که گذشته‌مان را دیدی، تو را به خانه‌ام آورده‌ام تا امیدم برای آینده را ببینی.\n\nاینجا در Har'mara، با دو تا از مردم بومی در صلح زندگی می‌کنیم: rutaaniها و fungarianها. رویاست من که این همراهی به بقیهٔ Harandar هم سرایت کند.\n\nبهتر است تو هم آن‌ها را بشناسی و صلحی را که با هم ساخته‌ایم ببینی." }
WoWFQ[86913] = { t = "کلبه‌ای در Har'mara", d = "بقیه پایین جمع شده‌اند. بیا. Orweyna مشتاق است ببیند سالم و در یک پارچه از آزمون‌ها بیرون آمده‌ای.", o = { "در Har'mara به Orweyna بپیوند." }, c = "به Har'mara خوش آمدی. خوشحالم که پس از آزمون‌ها سالم و کامل می‌بینمت.\n\nاین روستا خانهٔ Hagar و خیلی‌های دیگری است که Harandar را خانهٔ خود می‌دانند." }
WoWFQ[86914] = { t = "مراقبت از Har'mara", d = "Har'mara از دیرباز پناهگاه کسانی بوده که از درگیری‌های همیشگی میان rutaaniها و fungarianها دل بریده‌اند.\n\nاینجا یاد می‌گیرند با هم زندگی کنند. با هم کار می‌کنند، بازی می‌کنند و زندگی می‌کنند--در توازن.\n\nبسیاری از گذشتهٔ haranirها آموختی، از جمله ننگی عمیق‌مان. حالا کار امروزمان را می‌بینی: هماهنگی.", o = { "انجام تکالیف", "Watering Can (provided)" }, p = "سرشت طبیعی fungarianها و rutaaniها گسترده شدن است. گاهی همین به رشد بی‌رویه و از میان رفتن گونه‌های دیگر می‌انجامد.\n\nنگه‌داشتن این توازن مهم است، و همان وظیفه‌ای است که haranirها به‌عنوان سرپرستان Harandar انجام می‌دهند.", c = "گاهی هماهنگی و دوستی با کارهای کوچکِ خدمت کمک می‌گیرد.\n\nامیدوارم rutaaniها و fungarianهای اینجا تو را متحدی برای خودشان ببینند." }
WoWFQ[86929] = { t = "شورا گرد می‌آید", d = "نگهبانان Orweyna را بردند تا برای دیدار با شورا آماده شود. هر وقت آماده بودی، ما هم به مجلس می‌رویم.", o = { "با Halduron صحبت کن" }, p = "Orweyna به خاطر کارهایش بازخواست می‌شود.", c = "برای ماندن در میان ما باید ثابت شود که Goddess واقعاً تو را به یاری‌اش خوانده است.\n\nدر Den of Echoes، مکانی مقدس برای مردم ما، آزمون‌ها را پشت سر خواهی گذاشت." }
WoWFQ[86930] = { t = "کاشتن بذر", d = "بذر Eonka از Rift of Aln سرنخی است که دنبالش بودیم. ساکنان و گیاهان آنجا گویا در برابر lightbloom مصون‌اند!\n\nخودمان باید Rift را بکاویم. به Den برگردیم و برای قدم‌های بعد نقشه بچینیم.", o = { "در Den به Orweyna بپیوند" }, c = "به همان‌جا برمی‌گردیم که شروع شد، اما این بار برکت Goddess را با خود داری و شواهدی داریم که شاید بتوان جلوی گسترش lightbloom را ایستاند!\n\nراه پیش رو هنوز روشن نیست، اما حس می‌کنم نزدیک‌تر شده‌ایم." }
WoWFQ[86942] = { t = "هرس انتشار", d = "Powdercap گفت مسافران تازه‌وارد اولین کسانی بودند که نشانه‌های آلودگی lightbloom را نشان دادند. درست بعد از بازجویی تو!\n\nبدبختانه به نظر می‌رسد Koozat هم به این بیماری افتاده است. بازرگانان را از پا درآور و بعد کار Koozat را بساز. جانوری به آن خطرناکی نباید این‌طور این اطراف لگدکوب راه برود.", o = { "Koozat کشته شد", "Keem کشته شد", "Rizam کشته شد", "Teetem کشته شد" }, p = "من Koozat را از وقتی کوچک بود و در دست‌هایم جا می‌شد بزرگ کرده‌ام. Lightbloom به کسی رحم نمی‌کند که آلوده کند.", c = "پس تمام شد. متأسفم که این کار لازم شد، اما باید قبل از گسترش بیشتر، این آلودگی را هرس می‌کردیم." }
WoWFQ[86944] = { t = "بذرهای Rift", d = "وضعیت دارد آرام می‌گیرد، اما مطمئن شویم از خطر گذشته‌ایم. بروم ببینم حال Hagar چطور است.\n\nدوباره حال Eonka را بپرس و مطمئن شو هیچ نشانه‌ای از lightbloom در او نیست. او در طبقهٔ بالایی کلبهٔ Hagar است.", o = { "بازجویی دوباره از Eonka", "جمع‌آوری کیسهٔ بذر براق", "تحویل کیسهٔ بذر براق" }, p = "بیایید امیدوار باشیم Eonka دست‌نخورده مانده باشد.", c = "Eonka و بذرهایش از Lightbloom اثری نبرده‌اند. باورنکردنی است! ممکن است چیزی در rift باشد که Lightbloom را مهار می‌کند؟" }
WoWFQ[86956] = { t = "گل‌های مسافر", d = "Orweyna گفت rutaaniهایی از روستاهای دیگر به مهمانی آمده‌اند. این فرصت خوبی است که ببینیم وقتی دیوانهٔ نور نیستند چه‌طور آدم‌هایی‌اند.\n\nمن اینجا می‌مانم تا با Meeka حرف بزنم. تو با rutaaniهای مهمان صحبت کن و ببین lightbloom به خانه‌هایشان رسیده یا نه.", o = { "بازجویی از Rizam", "بازجویی از Teetem", "بازجویی از Eonka", "بازجویی از Keem" }, p = "باید جلوی گسترش Lightbloom را بگیریم! دانستن وسعت پخشش، در بلندمدت به نبردمان کمک می‌کند.", c = "پس هنوز هیچ نشانه‌ای از lightbloom در روستاهایشان نیست؟ Meeka هم دست‌نخورده به نظر می‌رسد و می‌گوید rutaaniها هرگز مثل این دیوانگانِ نور رفتار نمی‌کنند.\n\nهم نویدبخش است و هم کلافه‌کننده.\n\nخوشحالم که هنوز آن‌قدر نپخش شده، اما حدس می‌زنم به‌زودی موارد بیشتری پیدا کنیم." }
WoWFQ[86973] = { t = "بازداشتن آسیب در Har'mara", d = "rutaaniهای آلوده به Lightbloom به روستا حمله می‌کنند! Rizam و Teetem هر دو تسلیم آلودگی شدند. به نظر می‌رسد Eonka اثری نبرده، اما باید سراغ بقیه برویم.\n\nمن اینجا می‌مانم و مراقبش هستم. تو هر چه می‌توانی برای محافظت از Har'mara بکن. سر Rizam و Teetem هم برو.", o = { "کشته شدن Rutaaniهای Lightbloom" }, p = "باید منتظر این حمله می‌بودم. هر چه می‌توانی برای حفاظت از ساکنان اینجا بکن.", c = "کاری سخت، اما لازم. امید که تا راهی برای توقف کامل پیدا کنیم، این گسترش را کند کند." }
WoWFQ[88993] = { t = "Wey'nan's Ward", d = "برای تصاحب این یادگار، به Vale of Secrets سفر کن. Visionstone را پیدا کن. بر سطحش نقاشی‌های مقدسی هست، با ردپای دستی که در مرکز می‌درخشد.\n\nدستت را بر آن بگذار و روحت را بنمایان کن. تن‌ات به خوابی فرو خواهد رفت و جانت در رؤیاواهای گذشته قدم خواهد گذاشت.\n\nحذر کن: این رؤیاواها رؤیاهای ساده‌ای نیستند و خطرهایشان می‌تواند واقعاً جانت را بگیرد.\n\nبا دانسته‌ای که کشف می‌کنی پیش من برگرد.", o = { "تفکر در کنار Ancient Visionstone", "آموختن افسانهٔ Wey'nan's Ward" }, p = "سفرت حقیقت Wey'nan's Ward را آشکار کرد؟ بگو چه کشف کرده‌ای.", c = "قصه‌ای حیرت‌انگیز، شایستهٔ ثبت. با نقاش آن را زنده نگه می‌دارم تا برای همیشه در پژواک‌های مردم ما بماند. این یادگار را بپذیر--نشانهٔ قدردانی من از زحمت تو.\n\nفعلاً به کاویدن بایگانی‌مان ادامه می‌دهم، در جست‌وجوی یادگارهایی که فریاد فهمیدن سر می‌دهند.\n\nوقتی دنیا رازهای بیشتری زمزمه کرد، پیش من برگرد." }
WoWFQ[88994] = { t = "The Cauldron of Echoes", d = "اعصار بی‌شمار، Cauldron of Echoes در سایه آسوده است، کارکردش زیر غبار زمان پنهان.\n\nوقتی نخستین بار راه Zur'ashar را در پیش گرفتم، استادم از اهمیتش می‌گفت--یادگاری گره‌خورده با خودِ سرچشمهٔ نژاد ما. با این حال رازهایش حتی از آنان دور ماند... معمایی بی‌پاسخ.\n\nحالا باز صدایمان می‌کند.\n\nمی‌خواهی آنچه فراموش شده را کشف کنی؟ حقیقت در درون منتظر است، و من تا ابد وام‌دار کشفت خواهم بود.", o = { "تفکر در کنار Ancient Visionstone", "آموختن دربارهٔ Echoes of Sai'alyo" }, p = "سفرت حقیقت Cauldron of Echoes را آشکار کرد؟ بگو چه کشف کرده‌ای.", c = "چه داستان شگرفی!\n\nچه کنایه‌ای که قصهٔ Sai'alyo، نخستین Zur'ashar، به دست زمان گم شد. زحمت تو ما را برای فهمیدن این حلقهٔ گم‌شدهٔ تاریخ‌مان نزدیک‌تر می‌کند.\n\nلطفاً این یادگار را به نشانهٔ قدردانی از وقف تو بپذیر.\n\nفعلاً به کاویدن بایگانی‌مان ادامه می‌دهم، یادگارهایی که هنوز آرزوی کشف دارند.\n\nوقتی زمزمه‌های دنیا تو را به من برگرداند، بازآی." }
WoWFQ[88995] = { t = "Aln'hara's Bloom", d = "وقتی جوان بودم در راه Zur'ashar، قصه‌ای از هدیهٔ Aln'hara شنیدم: «نشانه‌ای از Goddess، حس‌شدنی در سکوت.»\n\nبدبختانه همهٔ کسانی که آن رویداد را از نزدیک تجربه کردند پیش از آنکه ما راز رنگ مخصوص‌مان را بدانیم از دنیا رفتند.\n\nمی‌شود در خاطره‌ای که این شکوفه را احاطه کرده قدم بگذاری و ببینی این نظریه درست است یا نه؟", o = { "تفکر در کنار Ancient Visionstone", "آموختن دربارهٔ هدیهٔ Aln'hara" }, p = "بگو چه دیدی، و ما مطمئن می‌شویم این خاطره دیگر گم نشود.", c = "چه حقیقت لطیفی کشف کردی! Aln'hara با تندر نگفت، نه به پیکر برگشت، که با صبر، حضورش را نمایاند.\n\nتو به بی‌صدایان صدا دادی، و با این کار، لحظه‌ای را به مردم‌مان پس دادی.\n\nلطفاً این نشانه را به یاد سفرت ببر.\n\nو اگر روزی دنیا دوباره خاموش شد، برگرد. من منتظر زمزمهٔ بعدی خواهم بود." }
WoWFQ[88996] = { t = "شعلهٔ بی‌پژواک", d = "سرنوشت شعلهٔ بی‌پژواک در گرو زمان گم شده است. در طول اعصار، زمزمه می‌شد که آن فانوس، دربرگیرندهٔ قدرت خودِ Aln'hara است. اما حالا، خفته است--پوسته‌ای که حتی یک سوسوی درونش نمانده. شاید تو بتوانی رازهایش را آنجا که دیگران شکست خورده‌اند آشکار کنی؟ گام‌های Obayo، نخستینِ Shul'ka، از نو بپیمای و شاهد شکوه این یادگار و حقیقتِ هدفش باش.", o = { "مراقبه در Ancient Visionstone", "آموختن دربارهٔ شعلهٔ بی‌پژواک" }, p = "رازهای شعلهٔ بی‌پژواک را کشف کردی؟", c = "شعله‌ها را برای آنکه نگذاریم آن هیولا همه‌مان را نابود کند به پایان رسانده‌اند?! شنیده‌ام این موجود حالا با نام Morta'ka the Sundered Echo شناخته می‌شود. چقدر بجا.\n\nاین هم برکت است هم بدیمنی. چه‌قدر ممکن بود امروز Rift of Aln متفاوت باشد اگر شعله هنوز در فانوس می‌رقصید؟\n\nبه‌زودی برگرد، <name>. تو و من کارهای کشف‌ناشدهٔ بیشتری داریم." }
WoWFQ[88997] = { t = "Russula's Outreach", d = "دستهٔ نیزه‌ای خورده‌آفتاب، آویخته از رشته‌های قارچ کم‌رنگ، در سکوت نگهبانی می‌دهد. بزرگان نامش را Russula's Outreach می‌گذارند، اما هیچ قصه‌ای با قصهٔ دیگر هم‌نظر نیست که آن کمک‌رسانی چه بود، و چه کسی را از مرگ رهاند.\n\nآیا این سلاح با خشم بالا رفت، یا با مهر پایین؟\n\nیادگار اینجا جوابی نمی‌دهد، فقط کششی ناتمام به سوی مزارع قدیمیِ هرس دارد.\n\nبا کشش برو. ردپای گم‌شده در پوسیدگی و شایعه را دنبال کن، و بگذار رؤیاواه‌ها از آنچه تاریخ فراموش کرد بگویند.", o = { "تفکر در کنار Ancient Visionstone", "آموختن دربارهٔ میراث Russula" }, p = "سفرت اسرار Russula's Outreach را آشکار کرد؟", c = "فریاد Russula، «نکشیدشان،» حالا که دیدیم او تا چه حد پا کشید و چه زخم‌هایی به تنتن نشست تا Harandar از پاره شدن خودش بر خودش رهایی یابد، به‌مراتب رساتر می‌گیرد. کردارش، با اندازه‌ای مهر که حاجت بود، آیین هرس ما را نرم کرد.\n\nگام‌های تو این توازن فراموش‌شده را پس آورد، <name>. این یادگار را با قدردانی من بردار، و وقتی سرزمین دوباره صدا زد برگرد. مطمئنم حقیقت‌های خاموش بیشتری زیر هاگ‌ها انتظار می‌کشند." }
WoWFQ[88998] = { t = "ریشهٔ جهان", d = "Root of the World نخستین هدیهٔ سرزمین به haranirها است، یا دست‌کم چنین گفته شده است. بسیار چیزها را دربارهٔ اینکه این عصا چطور به دست قومم رسید از یاد برده‌ایم. اما ریشهٔ ماجرا، اگر بگذارید، به روزگاری نزدیک به زمانی برمی‌گردد که haranirها نخستین بار پای به Harandar گذاشتند. گمان دارم با هم می‌توانیم گذشتهٔ گمشدهٔ آن را آشکار کنیم. می‌دانیم که Ruilla the Huntress چهرهٔ محوری رویدادهایی بود که به آفرینش این عصا انجامید. برو و تاریخ را از چشم او ببین.", o = { "به Vale of Secrets سفر کن تا تاریخچهٔ Root of the World را بیاموزی.", "مراقبه در Ancient Visionstone", "آموختن افسانهٔ Root of the World" }, p = "دربارهٔ Root of the World آموختی؟ چه حقیقت‌هایی کشف کردی؟", c = "چه تاریخچهٔ شگفت‌انگیزی! Ruilla the Huntress عصا را برداشت تا هم نخستین Rootwarden شود و هم نخستین کس از ما که Rootways را پیمود.\n\nاندوهناک است که با آنکه در جهان بالا بسیار چیزها عوض شده، بسیار چیزها هم عوض نشده.\n\n<name>، دوباره پیش من بیا وقتی که سرزمین یک بار دیگر تو را راهنمایی کرد." }
WoWFQ[88999] = { t = "Sky's Hope", d = "Sky's Hope: سنگی که افسانه می‌گوید از آسمان افتاد. جز آنکه نماد امید شمرده می‌شود، کم می‌دانیم.\n\nاما چرا؟\n\nقدم زدن در راه جد باستانی‌مان، Awe'ohna، شاید بر ماجرا روشنی بیندازد.", o = { "تفکر در کنار Ancient Visionstone", "آموختن افسانهٔ Sky's Hope." }, p = "...", c = "مگر می‌شود Awe'ohna در جست‌وجوی Cradle همان امیدی را یافت که دنبالش بود؟\n\nدرست است که Goddess بازگشت و آسمان دیگر تیره نیست، اما چطور؟ و مگر او واقعاً به آنجا رسید؟\n\nبه نظر می‌رسد جواب‌های‌مان ما را به سؤال‌های بیشتری رسانده است." }
WoWFQ[89034] = { t = "سوزاندن Bitterbloomها", d = "rutaaniهای آلوده به Lightbloom مشغول پخش آلودگی در روستا هستند. این گیاه نشانه‌های روشنی از بیماری نشان می‌دهد.\n\nهر گیاهی را که با آن‌ها تماس گرفته نابود کن. باید مهارش کنیم!", o = { "سوزانده شدن Bitterbloomها" }, p = "نباید گذاشت Lightbloom بپخشد. هماهنگی Har'mara ظریف و شکننده است. باید سالم نگهش داریم.", c = "خوب بود، <name>. امید که Har'mara به واحهٔ آرام روزهای رسیدن‌مان برگردد." }
WoWFQ[90094] = { t = "پژواک شکار", d = "haranirها درنده و بی‌رحم‌اند--زیرک و زبردست. با گذر زمان، ترسناک‌ترین جانوران کوه شدیم.\n\nجانوران فراوان دانا و قدرتمندی در تپه‌های کوه قدیمی‌مان می‌گشتند. اما با زمان، بر همه‌شان چیره شدیم.\n\nامروز، تو همان‌طور که ما روزگاری می‌کردیم شکار می‌کنی.", o = { "فعال کردن visionstone دوم", "کشته شدن Razorquill Remembrance", "کشته شدن Pangquill Reminiscence", "در گوشهٔ شمال‌غربی Den of Echoes با Kassameh صحبت کن." }, c = "ثابت کردی شکارچی‌ای توانا مثل اجداد قدیم‌مان هستی. اما صرف قوی‌تر بودن، آرامش ذهن مردم‌مان را تأمین نکرد." }
WoWFQ[90095] = { t = "پژواک ندا", d = "وقتی haranirها بی‌قرار شدند، به دنبال هدف‌های تازه گشتند. بعضی نگاهشان به بالا، به ستاره‌ها و ماه بود. بعضی دیگر، مثل Hara'ti، ندایی از عمق دنیا شنیدند.\n\nلحظه‌ای که نخستین Hara'ti آوازی را که از ریشه‌ها پژواک می‌گرفت شنید، فهمیدیم هدف تازه‌ای یافته‌ایم. به دنبال سرچشمهٔ آوا می‌رفتیم تا حقیقتش را خودمان کشف کنیم.\n\nاما راه دشواری بود. هیولاهای سنگی عجیب راه‌مان را سد می‌کردند.", o = { "فعال کردن visionstone سوم", "کشته شدن Observer Talos", "درون Den of Echoes به Kassameh بپیوند." }, c = "حالا می‌دانی Hara'tiها چطور راه ریشه‌ها را در پیش گرفتند.\n\nیک آزمون واپسین باقی است. سخت‌ترین، اما مهم‌ترین‌شان.\n\nHagar منتظرت است و تو را به چالش بعدی راهنمایی می‌کند." }
WoWFQ[90467] = { t = "قصه‌های آسمان", d = "صبر کن... تو اصلاً rutaani نیستی! مگر تو یکی از همان «غریبه»‌هایی نیستی که Saku و Orkon مدام ازش حرف می‌زنند؟\n\nاوه! یک ایدهٔ عالی به سرم زد. می‌دانی Goddess روزگاری حیوان خانگی داشت؟ شایعه است وقتی Goddess ناپدید شد، Aln'sharan آن‌قدر دلش شکست که به بلندترین ریشه‌های Harandar پرواز کرد و دیگر دیده نشد. اما هر چند گاهی، بیرون می‌آید تا غذا پیدا کند... و فلس‌هایش مثل skyglass می‌افتد!\n\nمن می‌خواهم جمع‌شان کنم. رویایم این است که Aln'sharan را از نزدیک ببینم! کمکم می‌کنی؟", o = { "Stray Skyshards" }, p = "Aln'sharan قصه‌ای است که به بچه‌های haranir می‌گوییم تا خرده‌شیشه‌هایی را که هر چند گاهی بر Harandar می‌بارد توضیح دهیم.\n\nبیشترها با بزرگ شدن، دنبال اژدهایان آسمانی را رها می‌کنند. اما قلب Kuri همیشه سرشار از پندار است.", c = "Goddess نگهدارمان باشد. ذهن Kuri همیشه در ریشه‌ها گم است." }
WoWFQ[90468] = { t = "اِه، کارهای خانه!", d = "خب، راستش یک چیز «متفاوت» هم هست که قرار است در Cascades انجام بدهم. نوبت من است که برگ saptor برای خورش جمع کنم. چه عذابی است. برگ‌های saptor نه‌تنها به‌طرز وحشتناکی تلخ‌اند، بلکه شکار saptorها هم به‌کلی سرگرم‌کننده نیست! حتی خون‌ات را قبل از مردن‌شان جاری نمی‌کنند.\n\nولی هست! احتمالاً تو به اندازهٔ من فرصت جنگیدن با saptorها را نداری. شاید وقتی دنبال skyglass می‌گردی، چند تا هم برای من جمع کنی؟ می‌دانی دیگر. چون یک‌بار برای همیشه در همان حوالی هستی.", o = { "برگ سالم Saptor" }, p = "وای بر تو، Kuri...", c = "Kuri به‌اندازه‌ای که درنده است، خیال‌باف هم هست، اما عادت بدی هم دارد: فراموش کردن کارهایش. از سهم تو برای جامعه‌مان ممنونم، هرچند وقتی Kuri برگردد باید سرزنشش کنم." }
WoWFQ[90469] = { t = "ادامه بده، Kuri سرکش", d = "آه، همین Kuri. به سنت‌ها و قصه‌های کهن ما چنگ زده... شاید هم بیش از حد. میان ارج نهادن به راه‌های کهن‌مان و تعقیب آنها تا غارهای خطرناک فرق هست. می‌ترسم در جست‌وجوی Aln'sharan از آب دربی‌آید. نمی‌روی دنبالش؟ به نظر می‌رسد به تو اعتماد دارد، حالا که تو را هم‌دست و هم‌داستان خودش در این مأموریت می‌بیند. لطفاً او را سالم به خانه برسان.", o = { "Kuri را در Dreth'amar Cavern پیدا کن.", "Kuri پیدا شد" }, p = "مطمئنم Kuri حالش خوب خواهد بود. سرش توی ریشه‌هاست، اما جنسش از جنس محکم‌هاست. اما با Harandar که این اواخر این‌قدر ناآرام بوده، ترجیح می‌دهم محتاط باشم تا پشیمان.", c = "ا-باشه... پس شاید کمی از تاریکی می‌ترسم. اما این دلیل نمی‌شود که نروم داخل!\n\nتو هم همراهم می‌آیی، نه؟ احتمالاً کلی skyshard توی آنجا پیدا می‌شود!" }
WoWFQ[90470] = { t = "نرخاجی Skyglass", d = "بزرگسال‌ها هر جور وسیله‌ای در غار‌های اطراف پیدا می‌کنند که در روستا به کارمان می‌آید. خیلی از جونور‌هایی که در غار‌ها زندگی می‌کنند، مخصوصاً عاشق جمع‌کردن skyglass هستند. فکر کنم به نظرشان برق می‌زند.\n\nاما این به‌درد ما می‌خورد! یعنی می‌توانیم برویم و یک عالمه skyglass برداریم. تو برو توی غار و مطمئن شو جا امن است، بعد من هم می‌آیم داخل و هرچه بتوانم حمل کنم جمع می‌کنم!\n\nبا این روال، خیلی زود می‌توانیم Aln'sharan را احضار کنیم.", o = { "هرچه Kuri می‌تواند از Dreth'amar Cavern در Harandar بار ببرد، Skyglass جمع کن.", "Skyglass بازیابی شد", "اولین کپه skyglass بازیابی شد", "دومین کپه skyglass بازیابی شد", "سومین کپه skyglass بازیابی شد", "آخرین کپه skyglass بازیابی شد", "[DNT] Kill Credit کشته شد", "Agitated Rootbat کشته شد", "Slimes کشته شد", "Mushrooms کشته شد", "Mildewed Enmity کشته شد" }, p = "زود باش دیگر! باید عجله کنیم، قبل از اینکه مامان زیادی نگران شود.", c = "آره! آره، آره، آره! چه عالمه زیادی!\n\nAln'sharan حتماً متوجه می‌شود. احتمالاً همه skyglass‌هایش را پس می‌خواهد!" }
WoWFQ[90474] = { t = "افسانهٔ Aln'sharan", d = "همین است! هر تکه skyglass که می‌شد حمل کرد را داریم.\n\nافسانه می‌گوید Aln'sharan اشک‌های بلوری می‌ریزد تا در غم نبودِ Goddess عزاداری کند. شاید اگر بلورها را به خودش پس بدهیم، دیگر آن‌قدر غمگین نباشد؟ شاید آن‌وقت حاضر شود خودش را به ما نشان دهد!\n\nدر روستا منتظرم باش. فکر می‌کنم جای بی‌نقصی برای پیشکش‌مان می‌شناسم.", o = { "پرتاب Skyshardها" }, p = "بجنب! نمی‌خواهیم فرصتمان را از دست بدهیم! ضمناً این‌همه skyglass سنگینی می‌کند. مگر دست‌ات شکسته که یکی‌اش را نمی‌گیری?!", c = "می‌دانی... فکر می‌کردم اگر جواب ندهد غمگین می‌شوم، اما واقعاً حس خوبی دارم!\n\nهنوز باور دارم. جادوی زیادی در این دنیاست. و اگر هم Aln'sharan دقیقاً همان چیزی نباشد که من فکر می‌کردم... قصه‌اش به دلیلی هنوز وجود دارد. و برای من همین مهم است، فکر می‌کنم." }
WoWFQ[90533] = { t = "برو Orweyna را بیاور!", d = "هی! آقای قهرمان!\n\nببین، قسم می‌خورم خوشحالم که می‌بینمت. فقط همین الان در یک وضعیت دیپلماتیک گرفتار شدم.\n\nمی‌شود بروی Orweyna را بیاوری اینجا؟ ببین می‌تواند این جانور را راضی کند بگذارد برم؟\n\nمن که عروسک الککی نیستم، به خدا.", o = { "در Den با Orweyna صحبت کن", "پیشنهاد دادن عروسک دست‌ساز به Nahuut", "Handcrafted Plush (Provided)" }, p = "هرگز بدون پیشنهاد چیز بهتری، سعی نکن چیزی را از جانداری مثل این بگیری.\n\nاز دست دادن یک دوست دیگر به این شیوه برایم دردناک است.", c = "خوشحالم که Monte به این سفر آمد. اما می‌بینم اینجا به همان اندازه که من در Undermine سرگردان بودم، او هم از آب در نمی‌آورد." }
WoWFQ[90534] = { t = "خانهٔ haranirها", d = "مشتاقم خانه‌ام را به Monte نشان بدهم، اما می‌دانم خیلی متفاوت است از آنچه به آن عادت دارد.\n\nهمراه‌مان بیا تا با مردمم دیدار کند.", o = { "دکمهٔ Shredder Gazlowe را فشار بده", "برداشتن Hand Claws", "چشیدن سوپ قارچ خوشمزه" }, c = "نمی‌توانم بگویم تا حالا جایی مثل این دیده‌ام. اما دوستش دارم. می‌فهمم چرا haranirها به اینجا کشیده شدند. چطور Orweyna اینجا بزرگ شد و هر چه آموخت، همین‌جا آموخت.\n\nاِه، ببین من چه احساساتی شدم. بعدش چی؟" }
WoWFQ[90535] = { t = "اثری از خود به جا بگذار", d = "یکی از چیزهایی که برای haranirها خیلی مهم است گذشته‌مان است. بعضی از ما توان شنیدن Goddess را از خود می‌گیرند، اما همه‌مان به آن‌هایی که قبل از ما بودند پیسته‌ایم.\n\nتو و Gazlowe حالا بخشی از تاریخ ما هستید. حق دارید در Den اثری از خود به جا بگذارید، تا وقتی که Den برپاست.\n\nبرو، با دست نقاشی‌شده به دیوار بزن، و بدان که به همان سنگی می‌زنی که نسل‌های پیش از تو می‌زدند.", o = { "مالیدن رنگ", "گذاشتن نشان رنگ" }, p = "ما مدام خود را نو می‌کنیم، حتی وقتی به گذشته‌مان وفاداریم. باید بیشتر به این یادم باشد.", c = "همین. حالا بخشی از Harandar هستی." }
WoWFQ[90537] = { t = "دیرشکفته‌ها", d = "خوشحالم که دوباره می‌بینمت، <name>. Orweyna گفت شاید بتوانی در کاری کمکم کنی.\n\nگروهی از rutaani قرار بود اوایل امروز به اینجا برسند، اما دیر کردند. از Blooming Terrace همراه استادم، Ru'gar، راه افتاده‌اند و نگرانم که در راه به دردسری خورده باشند.\n\nمی‌توانی در امتداد جاده از اینجا تا Terrace را جست‌وجو کنی؟ من از آن‌سو بالا می‌آیم، و اگر چیزی پیدا نکردیم، در میانه راه به هم می‌رسیم.", o = { "گروه گمشده rutaani و haranir را پیدا کن.", "به دنبال کاروان گمشده بگرد", "Empty Seed Sack", "Empty Seed Sack جمع‌آوری شد" }, p = "آهسته باش، حالا. دشمن نزدیک است.", c = "به Fungal Cleft خوش آمدی، <name>. fungarian‌های اینجا از آن‌هایی که در Har'mara هستند ناپایدارترند.\n\nآن‌ها هیچ مفهومی از تعادل ندارند و می‌کوشند هاگ‌هایشان را به هر سو پخش کنند؛ به‌طوری که rutaani‌های نزدیک Blooming Terrace را در ازدحام فرو برده‌اند و تهدید می‌کنند به بقیه Harandar هم سرریز کنند.\n\nrutaani‌های اسیر باید جایی درون سکونتگاه باشند." }
WoWFQ[90540] = { t = "نجات Rutaani", d = "آن‌سوی تپه، در شمال اینجا، روستایی از fungarian‌هاست: Fungal Cleft. فکر می‌کنم rutaani‌های گمشده را به آنجا برده‌اند.\n\nاگر زود آن‌ها را پس نگیریم، سرنوشت وحشیانه‌ای در انتظارشان است. fungarian‌ها معمولاً برای کار تکثیرشان میزبان‌هایی را ترجیح می‌دهند که از پیش مرده باشند. اما این‌های اینجا به‌طرز عجیبی خشن‌اند. حیوانات و rutaani‌هایی دیده‌ام که از قارچ پوشیده شده‌اند و هنوز تکان می‌خورند! این طبیعی نیست.\n\nبه Fungal Cleft برو و ببین می‌توانی مسافران گمشده را نجات بدهی یا نه.", o = { "5 Captured Rutaani را نجات بده.", "Captured Rutaani نجات یافت" }, c = "کار خوبی انجام دادی، <name>. دیدم rutaani‌های آزادشده دارند به‌سوی Har'mara می‌دوند.\n\nاین fungarian‌ها در تعقیبشان بودند، اما من غافلگیرشان کردم." }
WoWFQ[90569] = { t = "دوباره توی کیسه", d = "چه وضع به‌هم‌ریخته‌ای. کیسه‌ای که پیدا کردی قرار بود پر از دانه باشد. آن دانه‌ها بخشی از یک پروژه پرورش مهم هستند که Ru'gar رویش کار می‌کرد.\n\nبه نظر می‌رسد fungarian‌ها وقتی rutaani‌ها را اسیر کردند، دانه‌ها را با خودشان بردند.\n\nحالا که به دنبال rutaani‌ها می‌گردی، ببین می‌توانی دانه‌های دزدیده‌شده را بازیابی کنی یا نه.", o = { "6 Stolen Seeds را جمع کن.", "Stolen Seeds" }, p = "تاب نمی‌آورم فکر کنم fungarian‌ها با دانه‌هایی که Ru'gar با دقت پرورش می‌داد چه می‌کنند. او با rutaani‌ها روی گیاهانی کار می‌کرد که مقاوم‌تر بودند و محصول بیشتری می‌دادند.\n\nنباید زحماتش از بین برود.", c = "چه دانه‌های زیادی پیدا کردی! ممنونم.\n\nاین دانه‌ها برای Ru'gar خیلی مهم بودند. من زیاد درباره‌ی باغبانی نمی‌دانم، اما شاید بتوانم امتحانش کنم." }
WoWFQ[90601] = { t = "جمع‌کردن Glowshroom", d = "Ru'gar همیشه برایم تعریف می‌کرد که چطور قاچاقی به غار نزدیک می‌رفت تا glowshroom برداشت کند. به نظر می‌رسید برای رشد دانه‌های tla'tak که پرورش می‌داد حیاتی بودند. می‌شود مقداری از قارچ‌های درونش را جمع کنی؟\n\nراستی، Ru'gar گفته بود که قارچ‌ها هنگام برداشت‌شدن خاصیت‌های عجیبی دارند. مطمئن نیستم منظورش چه بود، اما شاید بهتر باشد حواست جمع باشد.", o = { "6 Glowshroom را جمع کن.", "Glowshroom" }, p = "Ru'gar گفته بود که glowshroom‌ها وقتی با خاکی که در آن محصول کاشته بود قاطی می‌شوند، برداشت محکم‌تری به بار می‌آورند. که چطور اصلاً به این پی برده بود، هیچ‌وقت نخواهم فهمید.\n\nدلم می‌خواهد کار Ru'gar را ادامه بدهم. حالا که اینجاییم، بهتر است هرچه می‌توانیم جمع کنیم.", c = "آه، برگشتی! و با این همه glowshroom. عالی است. امیدوارم چیز عجیبی برایت پیش نیامده باشد.\n\nممنون که همه این‌ها را جمع کردی. مدتی طول می‌کشد تا روش‌های Ru'gar را از نو کشف کنم، اما حالا امید دارم که بتوانیم کارش را ادامه دهیم." }
WoWFQ[90602] = { t = "Gomphusta", d = "آخرین خواهش را هم از تو دارم. چند بار fungarianها از رهبرشان، Gomphusta، حرف زدند. به نظر می‌رسد او پشت موج خشونت‌شان است و باعث دزدیدن بذرها.\n\nوقتی در غار هستی، پیدایش کن و کارش را بساز. بدون دسیسه‌چینی‌های Gomphusta، بقیهٔ fungarianها به آشوب می‌افتند و کمبند نمی‌توانند درست بچینند.", o = { "Gomphusta کشته شد", "یادداشت‌های کشت", "کلید حکاکی‌شده" }, p = "fungarianها همیشه این‌قدر خشن و پرتها نیستند. Gomphusta باید نیروی محرکشان باشد. به نظر می‌رسد اوست که موجودات زنده را با هاگ آلوده می‌کند.\n\nبا رفتنش، شاید fungarianها به حالتی متوازن‌تر برگردند.", c = "این چیست؟ یادداشت‌های Ru'gar دربارهٔ تلاش‌های کشتش!\n\nفوق‌العاده است. حالا می‌توانم کارش را بازسازی کنم.\n\nکار Gomphusta را هم خوب تمام کردی. امید که fungarianها را به هم بریزد و مسافران جاده‌ها را امن‌تر نگه دارد." }
WoWFQ[90615] = { t = "دعوت به Grudge Pit", d = "تو... فرق داری! تا حالا به Grudge Pit رفته‌ای؟\n\nGrudge Pit جای خوبی است! پر از جنگیدن و هورا کشیدن و fungarian. بوی گندیدگی هم دارد!\n\nBoletus همیشه دنبال جاندار قوی می‌گردد تا در Grudge Pit بکشد. یا بگذارد بکشند.\n\nجاندار قوی هستی؟ باید به Pit بیایی!", o = { "در Grudge Pit با Boletus صحبت کن." }, c = "تو انگار قبل از گندیدن، جنگ سختی راه می‌اندازی.\n\nخیلی جالب خواهد بود!" }
WoWFQ[90616] = { t = "تو قوی؟", d = "تو قوی به نظر می‌رسی.\n\nباید خودت را در میدان نبرد ما بیازمایی.\n\nببین کنار fungarianهای قوی چه می‌شوی.", o = { "نشان دادن توانایی‌ها" }, p = "خیلی fungarian تماشا می‌کنند جنگ را.\n\nهمیشه هیجان‌انگیز است!", c = "ما، اِم... تو خیلی قوی هستی.\n\nچطور، اِم...؟ تو خیلی فرق داری.\n\nبه fungarianها یاد بدهی، مثل تو فرق کنند؟" }
WoWFQ[90617] = { t = "چند قارچ خوش‌گذران", d = "تو خیلی قوی هستی، <name>.\n\nبه fungarianها جنگیدن یاد می‌دهی؟\n\nخیلی چیز می‌توانیم از تو یاد بگیریم.\n\nخیلی fungarian جنگ را تماشا می‌کنند.\n\nبپرس کی می‌خواهند در Pit قوی شوند.", o = { "با Motta صحبت کن", "پیدا شدن داوطلبان" }, p = "fungarian برای یاد گرفتن پیدا می‌کنی؟ مثل <name> در Pit قوی شوند؟", c = "پیدا کردی که یاد بدهی؟\n\nقدم اول جنگیدن است، ببین چه می‌شود کرد!" }
WoWFQ[90619] = { t = "آنچه آن‌ها را نمی‌کشد", d = "تیم داریم؛ حالا آماده جنگیم.\n\nتیمت را ببر جایی خالی. جنگ تمرینی بکنید، و ببینید چه کار از دستتان برمی‌آید.", o = { "با هم‌تیمی‌هایت گرم بگیر.", "با Brakko گرم بگیر", "با Ziny گرم بگیر", "با Tuktuk گرم بگیر" }, p = "ما با تو می‌جنگیم؟\n\nتو قوی هستی.\n\nبا هم جنگیدن تمرین خوبی برای قوی‌شدن است.", c = "چشم‌ها باز شد، <name>! ما هم می‌توانیم قوی باشیم.\n\nقوی خواهیم شد، مثل تو!\n\nوقتی آسیب ببینند، fungarian‌ها قوی‌تر می‌شوند. تو زیاد زدی، ما خیلی قوی‌تر شدیم.\n\nباید برویم به Boletus بگوییم آماده‌ایم!" }
WoWFQ[90620] = { t = "به میدان", d = "TeamName؟ بد نیست. خوشم آمد!\n\nتو و TeamName بروید پایین، و ما حرف می‌زنیم.\n\nتو با Spore Storm می‌جنگی. اگر بردی، با Cap Clash بجنگ.\n\nاگر بردی، با Fungus Force بجنگ.\n\nهمیشه‌برنده‌ها Glow Guard هستند. تو نمی‌توانی آن‌ها را ببری.\n\nفرار نکن! فرار کردن یعنی باخت بزرگ، بزرگ.", o = { "با تیم‌تان برو بجنگ.", "با Motta صحبت کن", "از مدخل رد شو", "Fungus Force شکست خورد", "Tuktuk از Pit فرار می‌کند", "Spore Storm شکست خورد", "Brakko از Pit فرار می‌کند", "Cap Clash شکست خورد", "Ziny از Pit فرار می‌کند", "در Grudge Pit بجنگ" }, c = "مطمئن بودم Brakko به‌اندازه کافی قوی است. با <name> قوی تمرین کرده بود!\n\nاما Brakko از sporeglider‌ها می‌ترسد. کلاهک را می‌خورند!\n\nBrakko خیلی ناراحت است که <name> را ناامید کرده.\n\nZiny و Tuktuk هم. همه فرار کردند.\n\nما فرار کردیم، و Fungal Fellosh باخت.\n\nاما چطور می‌شود فرار نکرد، وقتی sporeglider‌ها حمله می‌کنند؟" }
WoWFQ[90621] = { t = "سفر‌های قهرمانان کوچک", d = "تو به آن‌ها آموزش دادی. چرا فرار کردند؟\n\nهمه fungarian‌ها ذوق داشتند ببینند آیا یک <race> می‌تواند به fungarian‌ها یاد بدهد که چطور قوی شوند.\n\nیک بار دیگر امتحان می‌کنی، باشه؟\n\nاول کاری را که برای آماده‌کردنشان لازم است انجام بده.", o = { "به هر یک از اعضای تیم برای غلبه بر چالش‌هایشان کمک کن.", "با Motta صحبت کن", "Brakko یاری شد", "Ziny یاری شد", "Tuktuk یاری شد", "[DNT] Park Guardians", "[DNT] Brakko Parked" }, c = "حالا آموزش تمام شد، نه؟ بگذار ببینیم Fungal Fellowship چه کار‌هایی از دستش برمی‌آید." }
WoWFQ[90622] = { t = "قهرمانانی که هنوز شکست نخورده‌اند", d = "$p، PHTeamname حالا قوی‌تر به نظر می‌رسد! آماده‌تر. امیدوارم دیگر فرار نکنند.\n\nنبرد بعدی در برابر Glow Guard است. Glow Guard همیشه هیچ‌وقت نمی‌بازد.\n\nامیدوارم تمرین‌هایت نبرد را بهتر کند، پیش از آنکه TEAMNAME ببازد.\n\nتماشا کردنش جالب خواهد بود!", o = { "وارد Grudge Pit شو و Glow Guard را شکست بده.", "با Motta صحبت کن", "از مدخل رد شو", "وارد Grudge Pit شو", "Glow Guard را شکست بده", "[DNT] اعتبار کشتن: [DNT] Team is Parked کشته شد" }, p = "Grudge Pit همیشه دنبال قهرمانان تازه است، <name>. تا به حال، ما فقط داشتیم قهرمانان قدیمی را دوباره پیدا می‌کردیم.", c = "وای، شوکه شدم! Sporesworn توانست Glow Guard را شکست بدهد!\n\nمی‌دانستم <name> قوی است. اما نمی‌دانستم آیا تمرین می‌تواند کافی باشد.\n\nحتی یک fungarian هم روی Sporesworn شرط نبسته بود. فکر نمی‌کردیم بشود Glow Guard را شکست داد.\n\nحالا همه fungarian‌ها می‌دانند <name> بهترین معلم قوی‌شدن است!" }
WoWFQ[90733] = { t = "شنونده", d = "حالا که افسانه‌های ما را آموختی، نظر یکی از بزرگان ما را جلب کرده‌ای. او می‌خواهد تو را ببیند.\n\nاسمش Aksem است، و چیزهایی می‌داند که بقیهٔ ما هرگز نیاموخته‌ایم. تاریخچه‌ای که حتی در نقاشی‌ها پنهان مانده.\n\nبرو، خودت را معرفی کن. منتظرت است.", o = { "در Cradle با Aksem صحبت کن." }, p = "...", c = "بله، می‌خواستم با تو حرف بزنم.\n\nحقیقت‌های بسیاری پنهان مانده‌اند، حتی از کهن‌ترین haranirهای زنده. به آموختن ادامه بده و شاید روزی آشکار شوند.\n\nبه تاریخ ما احترام بگذار، و روزی بیشتر برایت خواهم گفت." }
WoWFQ[90734] = { t = "به نام الهه", d = "کاهن اعظم Aksem دوباره تو را طلب کرده است. گفت که تو تنها کسی نیستی که در جست‌وجوی دانشی درباره تاریخ ژرف Harandar است.\n\nنزد او برو. باور دارم همین حالا نیز مهمان دیگری نزد اوست که او هم مشتاق است این تاریخ پنهان را بیاموزد.", o = { "نزد Aksem در Den بازگرد.", "چای نوشیده شد" }, p = "چای افکارت را آرام می‌کند.", c = "از چای ممنونم، شاگرد.\n\nهمان‌طور که می‌بینی، تو تنها کسی نیستی که پرسش و بلندپروازی‌اش به یک اندازه است. همچنان جست‌وجو کن و همچنان بیاموز.\n\nبه‌زودی تو را برای درس بعدی فرا می‌خوانم." }
WoWFQ[90735] = { t = "عصای دزدیده‌شده", d = "این بار، داستانی برای تو ندارم.\n\nدر عوض، Aksem خواسته است که نزد او بروی تا در بازیابی یادگار بعدی به او کمک کنی. برو با او صحبت کن، و او بیشتر از کاری که باید انجام دهی برایت می‌گوید.", c = "خوب است. برگشتی.\n\nچیز مهمی دزدیده شده است، و می‌خواهم آن را بازیابی کنی و به Kassameh بازگردانی. آماده‌ای؟" }
WoWFQ[90736] = { t = "آن مال تو نیست", d = "rutaani‌های Blossoming Terrace حیله‌گرند. petalwing‌هایشان را آموزش داده‌اند تا هر چیز براقی را که از Den پایین می‌غلتد پیدا کنند و قاپ بزنند.\n\nو، به گمانم، گاهی چیز‌هایی را قاپ می‌زنند که طبیعتاً نیفتاده‌اند.\n\nپس می‌خواهیم آن چیز‌ها را پس بگیریم. و اینجاست که تو وارد ماجرا می‌شوی.\n\nبه درون تراس برو، و در به‌کارگیری زور برای رساندن یک پیام تردید نکن. آن زبانی است که ما همه می‌فهمیم.", o = { "8 Stolen Belongings را از Blossoming Terrace بازیابی کن.", "Stolen Belongings" }, p = "آن چیز‌های گم‌شده را پیدا کرده‌ای؟", c = "چیز‌های قابل توجهی پیدا کردی. از جمله...\n\n... صبر کن، این مال من است. فکر می‌کردم آن را گم کرده‌ام.\n\n<Seila زیر لب درباره پرنده‌های دزد حرف‌های رکیک می‌زند.>" }
WoWFQ[90737] = { t = "سرنخ‌های میان لانه‌ها", d = "به دنبال عصایی هستی به نام Root of the World؛ تنیده‌ای نیرومند از ریشه‌های درهم‌بافته، از روزگاری پیش از آنکه haranir به ژرفای کوه سفر کنند.\n\nجایش را هیچ چیز نمی‌گیرد، همان‌طور که Aksem می‌داند. پس اگر petalwing یک rutaani آن را دزدیده باشد، این ماجرا خجالت‌آور است. تنها راه آنکه همگان آبرویشان را حفظ کنند، پس گرفتن آن است.\n\nلانه‌های پرنده‌های بزرگ‌تر را بگرد. آن‌ها را آموزش داده‌اند تا دنبال اشیای باارزش‌تر بگردند.", o = { "سرنخ‌هایی درباره محل احتمالی عصای ریشه‌ای دزدیده‌شده آشکار کن.", "First Thiever's Nest جست‌وجو شد", "Second Thiever's Nest جست‌وجو شد", "Third Thiever's Nest جست‌وجو شد" }, p = "پیدا کرده‌ای که عصا ممکن است کجا باشد؟", c = "هیچی پیدا نکردی؟\n\nحیف شد.\n\nشاید جای درستی را نمی‌گردی.\n\n<Seila با نگاهی نافذ به تو خیره می‌شود.>" }
WoWFQ[90738] = { t = "به سوی Blossoming Terrace", d = "وقتی haranirها اولین بار به Harandar آمدند، عصایی با خود آوردند ساخته‌شده از ریشه‌های درختی بزرگ. آن درخت از پس سال‌ها رفته، اما ریشه‌هایش مانده است.\n\nوظیفهٔ ما بوده از آن عصا محافظت کنیم و نسل به نسل برسانیم. اما حالا دزدیده شده است.\n\nکار تو این است که پیدایش کنی و به Zur'Ashar Kassameh بازگردانی.\n\nبه مه‌های زیر Den برو و Shul'kaها را پیدا کن. در جست‌وجوت راهنمایی‌تان می‌کنند.", o = { "بیرون Blossoming Terrace با Shul'ka Seila دیدار کن." }, c = "درود بر تو، شاگرد Cradle.\n\nAksem پیغام داد که کسی را به این پایین می‌اندازد تا عصای گم‌شده را پیدا کند. زیاد از اهل Den کسی را نمی‌بینم، جز احمق‌هایی که سرگردان به این پایین می‌آیند.\n\nتو یکی از همان احمق‌ها نیستی، نه؟" }
WoWFQ[90739] = { t = "ریشه ماجرا", d = "به نظر نمی‌رسد هیچ نشانه‌ای از عصای ریشه‌ای میان لانه‌های دزدان پیدا کرده باشی. راستش، این چیز خوبی است.\n\nاما این آزمون چیز‌های بیشتری دارد، نه فقط پس گرفتن کالا‌های دزدیده‌شده. بله، این یک آزمون است. تو در پی دانشی پنهان می‌گردی. یعنی چیزی در اینجا جور در نمی‌آید، و پاسخ واقعی منتظر است تا پیدا شود.\n\nپس هر وقت آماده بودی آن پاسخ را بگیری، بیا من را پیدا کن.", o = { "Shul'ka Seila را دنبال کن و عصای گم‌شده را بازیابی کن.", "Seila دنبال شد", "Seila رویارو شد", "Root of the World بازیابی شد" }, c = "آفرین. بله، از Seila خواستم عصا را بردارد تا پایبندی تو را بیازماید.\n\nخودت را ثابت کرده‌ای. حق آن را یافته‌ای که بیشتر درباره آن، و درباره تاریخ ما، بدانی." }
WoWFQ[90740] = { t = "افسانه‌ای که باید شناخت", d = "بسیاری از رازها به من سپرده شده‌اند، و فایده‌اش این است که مجبور نیستم اغلب خودم را توجیه کنم.\n\nتو Root of the World را بازیابی کردی، همان‌طور که از تو خواسته بودم. حالا آن را نزد Zur'ashar Kassameh ببر و بیشتر درباره‌اش بیاموز.\n\nبعداً چیزهای بیشتری هم برایت خواهد بود.", c = "Root of the World! خوشحالم که می‌بینم به جای درستش بازگشته است.\n\nبیا، از تاریخش پرده برداریم و بیشتر بدانیم که ریشه‌ها چگونه Harandar را شکل داده‌اند." }
WoWFQ[90741] = { t = "بار دیگر به درون Rift", d = "Aksem دوباره خواستار توست. می‌گوید آماده است تا تو آیین نهایی را برای دانشی که می‌خواهد به تو بیاموزد، طی کنی.\n\nاعتراف می‌کنم که حسادتم می‌شود، اما به آزمون‌هایی که برای آماده شدن برای این دانش باید از سر بگذرانی، حسادت نمی‌کنم.\n\nبرو با Aksem سخن بگو و آن‌گونه که می‌گوید عمل کن. Orweyna نیز همراهت خواهد بود.", o = { "با Aksem صحبت کن، سپس در Rift of Aln با Orweyna دیدار کن.", "با Aksem صحبت کن" }, c = "<Orweyna با دقت و ثبات نفس می‌کشد، چشمانش کمی بی‌تمرکزند. سپس نگاهش را تیز می‌کند و رو به تو می‌کند.>\n\nخوشحالم که اینجایی. اعتراف می‌کنم که از آنچه خواهیم آموخت احساس نگرانی می‌کنم. تا جایی که یادم می‌آید، تنها یک داستان درباره‌ی الهه شنیده‌ام.\n\nدانستن اینکه داستان بیش از این‌هاست، مرا... پر از کنجکاوی و وحشت می‌کند.\n\nاما همان‌طور که Aksem گفت، دیگر راه بازگشتی نیست. و ما آماده‌ایم." }
WoWFQ[90742] = { t = "در نقاب Aln'hara", d = "همان‌طور که حالا خوب می‌دانی، موجودات درون Rift با جوهر Aln'hara سرشته شده‌اند. آنچه ما نیاز داریم، همان جوهر است که با آب آمیخته شود.\n\nAksem می‌خواهد که ما اینجا آب جمع کنیم و سپس جوهر Aln'hara را با آن عجین کنیم. فقط می‌توانم تصور کنم که شاید برای چه کاری از آن استفاده کنند.", o = { "در Rift of Aln آب جمع کن و موجودات را شکست بده.", "Rift of Aln Water جمع شد", "با جوهر Aln'hara عجین شد", "Water با جوهر Aln'hara عجین شد", "Rift Shade کشته شد", "Decaying Essence کشته شد", "Coalesced Spirit کشته شد", "Aln Oozeling کشته شد" }, p = "صدا اینجا همچنان به پای همیشه قوی است.", c = "انجام شد. اما قسم می‌خورم... حالا صدای الهه را با درد آمیخته می‌شنوم.\n\nقرار است چه چیزی بیاموزیم؟" }
WoWFQ[90743] = { t = "تقویت آیین", d = "خطرهای Rift of Aln را خوب می‌دانی، اما این بهترین جایی است که می‌توان برای آیینی که Aksem می‌خواهد انجام دهد، آماده شد.\n\nدر Rift بگرد و پیشکش‌ها را بگذار تا خودت را آماده کنی.", o = { "در Rift of Aln پیشکش‌های آیینی بگذار.", "پیشکش‌های آیینی گذاشته شد", "پیشکش آیینی کشته شد" }, c = "نیروی Aln'hara را خوب مهار می‌کنی.\n\nدارم به این فکر می‌کنم که چقدر احمقانه بود که تو را وادار کنم با من بجنگی." }
WoWFQ[90744] = { t = "Dreamrift: معمای بدشکل", d = "برای مرحله بعد، هرچه از دستمان برمی‌آمد آماده شدیم. حالا باید به ژرف‌ترین نقطه Rift of Aln برویم.\n\nبه درون Dreamrift.\n\nجایی چنان خطرناک که حتی Shul'ka هم در رفتن به آن تردید می‌کنند، اما ما باید برویم. Aksem به ما نیاز دارد تا نیرومندترین آمیزه Aln را که وجود دارد جمع کنیم.\n\nآماده‌ای؟", o = { "در Dreamrift Chimaerus را شکست بده.", "Dreamrift وارد شد", "Chimaerus کشته شد" }, c = "بارها از Rift of Aln جان سالم به در برده‌ای، اما آنچه در Dreamrift راه می‌رود وحشتی است در دسته‌ی خودش.\n\nحالا هر آنچه برای آیین لازم داری را در اختیار داری. شاید بگویم بخش سخت کار تمام شده، اما آن دروغ می‌بود.\n\nبخش سخت، دانستن حقیقت Cradle of Aln'hara است." }
WoWFQ[90824] = { t = "برادرم زنده است!", d = "En'liahn من را از Rift of Aln نجات داد. او برادر بزرگ‌ترم است. می‌دانم رفتن آنجا احمقانه بود، اما تقصیر من نبود!\n\nهمه فکر می‌کردند En'liahn مرده، اما همین صبح در تالاب دیدمش. وقتی من را دید، فرار کرد.\n\n<Chua looks sad.>\n\nهیچ‌کس اینجا باورم نمی‌کند و حالا هم نمی‌توانم بروم. کمکم می‌کنی دوباره پیدایش کنم؟", o = { "En'liahn را در Ahl'ua Wetland پیدا کن." }, c = "Chua تو را فرستاده؟ مگر باز آن بیرون است؟\n\nدستت را به من قرض نمی‌دهی؟" }
WoWFQ[90826] = { t = "آب‌های شفابخش Ahl'ua", d = "دلم می‌خواست Chua ندیده‌ام باشد. بهتر بود فکر کند مرده‌ام. به‌جایش، خودم را تبعید کرده‌ام.\n\nوقتی نجاتش می‌دادم در Rift of Aln گرفتار شدم. آن‌همه ماندن در آنجا پیوندم با Goddess را فاسد کرد--اگر به‌زودی قطعش نکنم، دیوانه‌ام می‌کند، یا بدتر.\n\nShul'ka‌ای که نجاتم داد قبول کرده در این راه استادم باشد. گفت بیایم اینجا و وسایلی برای آیینی جمع کنم که پیوند را قطع کند.\n\nباید آب‌های شفابخش نزدیک را جمع کنم. کمکم می‌کنی این کوزه را پر کنم؟", o = { "آب‌های شفابخش Ahl'ua", "En'liahn's Jug (provided)" }, p = "ممنون بابت کمکت، <name>.", c = "ممنونم، <name>.\n\n<En'liahn looks like he's getting worse.>\n\nامیدوارم این آب همان‌قدر نیرومند باشد که استادم می‌گوید. زهر قوی این جانداران به من می‌گوید برای جان به در بردن از آیین به آن نیاز خواهم داشت." }
WoWFQ[90827] = { t = "فقط قسمت‌های سمی", d = "استاد Shul'ka من گفت غده‌های سمی جانداران اینجا را جمع کنم. گفت برای آیین گسست، تا پیوندم را با Goddess قطع کنم، حیاتی‌اند.\n\n<En'liahn shakes his head in pain.>\n\nدلم نمی‌خواهد به این آیین برسم، اما آواز آشفته‌اش در سرم هر لحظه رساتر می‌شود و تمرکز را از من می‌گیرد.", o = { "بخش‌های سمی گیاه‌زاد" }, p = "مراقب این زهر باش. این جانداران بعضی از کشنده‌ترین‌های کل Harandar هستند.", c = "این باید بیشتر از حد کافی باشد.\n\nمراقبشان هستم. نمی‌خواهم پیش از موعد خودم را مسموم کنم." }
WoWFQ[90829] = { t = "دیدار با استادم", d = "وام‌دارتم، <name>. فکر نمی‌کردم کمکی برسد. استادم فقط راهنمایی می‌کند. می‌گوید راه Shul'ka همین است.\n\nبه لطف تو، هر چه برای آیین لازم داشتم دارم. ادامه می‌دهی با من؟ راه افتاده‌ام به سمت صخره‌ای در شمال‌شرق که مشرف بر Rift of Aln است.", o = { "دوباره به En'liahn بپیوند" }, c = "خوشحالم که آمدی. Amarakk استاد Shul'ka من است. می‌گوید کمک تو اکیداً ممنوع نیست.\n\nهر کمکی که بتوانم می‌گیرم." }
WoWFQ[90830] = { t = "راه، خودش را نشان می‌دهد", d = "قدم بعدی پیدا کردن محل آیین است. برای هر Shul'ka آینده‌ای متفاوت است.\n\nAmarakk می‌گوید باید خودم را به قدرت rift بسپارم--بخشی از من که به اینجا گره خورده راه را نشان می‌دهد.\n\nفقط همین را می‌توانم بگویم: درد دارد.\n\nهنوز با منی؟", o = { "با En'liahn صحبت کن", "پیدا شدن راهنمای اول", "پیدا شدن راهنمای دوم", "پیدا شدن راهنمای سوم", "پیدا شدن راهنمای چهارم", "پیدا شدن راهنمای پنجم", "پیدا شدن راهنمای واپسین" }, p = "می‌بینم رسیدی.", c = "حالا وقتش است ببینیم En'liahn جوان از آیین جان به در می‌برد یا rift می‌بلعدش." }
WoWFQ[90831] = { t = "کردن است که شدن می‌آورد", d = "اگر En'liahn می‌خواهد Shul'ka شود، باید یاد بگیرد تجلی‌های rift را به هم بریزد. گاهی یعنی بستن ترک‌های کوچک به محض باز شدن. بیشتر وقت‌ها، تجلی‌ها را همان‌جا که پیدا می‌کنیم می‌کشیم تا آن‌قدر زیاد نشوند که بقیهٔ Harandar را تهدید کنند.\n\nمسئولیتی بی‌پایان است که هر کدام از ما بر دوش می‌کشیم. برای همین Shul'ka هستیم.\n\nالبته این به آن شرط است که از آیین جان سالم به در ببرد، یا حتی زنده به محل آیین برسد.", o = { "به هم ریختن Rift of Aln" }, p = "می‌بینمت، <name>.", c = "برای کسی که Shul'ka نیست، خوب عمل کردی.\n\nبدبختانه Rift of Aln هرگز استراحت نمی‌کند. حدس می‌زنم برمی‌گردی." }
WoWFQ[90832] = { t = "وقتی صدایش خاموش می‌شود", d = "En'liahn همین حالا می‌خواهد ترکیب زهر و آب‌های شفابخش را بنوشد تا آیین آغاز شود. بیهوش خواهد شد و برای جانش خواهد جنگید.\n\nتجلی‌های rift این را حس می‌کنند، و دارند جمع می‌شوند.\n\n<name>، تو باید Wardها را بگذاری و با قدرتشان از او محافظت کنی در حالی که آخرین پیوندش را با Goddess قطع می‌کند، پیش از آنکه آوازش دیوانه‌اش کند.", o = { "قرار دادن Wardهای Shul'ka", "آغاز آیین گسست", "تکمیل آیین گسست" }, p = "هر چه رخ دهد، ثابت کرده‌ای می‌شود رویت کرد.", c = "تمام شد. یک کار دیگر هم باقی است وقتی En'liahn به هوش بیاید.\n\nاما اول، باید همین حالا rift را ترک کنیم. اینجا جای ماندن نیست." }
WoWFQ[90833] = { t = "آیین واپسین", d = "احمق. En'liahn هنوز از آیین ضعیف است و آماده نیست.\n\nفرار کرده تا با Morta'ka the Sundered Echo روبه‌رو شود. این آیین واپسینِ همهٔ کسانی است که می‌خواهند Shul'ka شوند، اما معمولاً فقط بعد از سال‌ها آمادگی انجامش می‌دهند.\n\nEn'liahn جان سالم به در نخواهد برد، و با مرگش فقط Morta'ka را نیرومندتر می‌کند. نجاتش می‌دهی، <name>؟", o = { "به En'liahn بگو آماده‌ای", "کشته شدن Morta'ka the Sundered Echo" }, c = "می‌دانم احمقانه بود و باید مرده می‌بودم. گیج شده‌ام که از آیین جان سالم به در بردم اما دیگر نمی‌توانم صدای Goddess را بشنوم. ببخشید، <name>. نباید آن کار را می‌کردم.\n\nدست‌کم تمام شد. حالا باید از Amarakk معذرت‌خواهی کنم. احتمالاً از من خلاص شده." }
WoWFQ[90834] = { t = "از این پس", d = "نمی‌دانم با از دست دادن پیوندم با Aln'hara چه حسی داشته باشم. دیگر دردی نیست... دیوانه نمی‌شوم، اما حفره‌ای در درونم است. می‌فهمی چه می‌گویم؟\n\nروی صخره به ما می‌پیوندی؟", o = { "بازگشت به En'liahn و Amarakk روی صخرهٔ مشرف بر Rift of Aln." }, c = "وام سنگینی به تو دارم، <name>. دست‌کم حالا می‌توانم در حین آموختن راه Shul'ka از مردمم محافظت کنم.\n\nتنها تأسفم این است که از Chua جدایم کرده است." }
WoWFQ[90957] = { t = "روز آیین ورود", d = "<name>، امروز روزی است که جای درست خودت را میان haranirها پیدا می‌کنی.\n\nRoot Tender Dalnir راهنمایات خواهد بود. راه او سنتی است و پر از تواضع، پس انتظار هیجان نداشته باش. تا آخر روز، نشان خودت را در Den of Remembrance خواهی زد. قصه‌ای که حالا شروع می‌کنی، مثل خود ریشه‌ها، بر قصه‌های قبل از تو بنا می‌شود و بنیان‌های Harandar را می‌رویاند.\n\nDalnir داشت drifterهای مهاجم را از ریشه‌ها پاک می‌کرد. قبل از رفتن پیش او، خودت هم چند تا از این آفت‌ها را پاک کن تا به Dalnir کمک کرده باشی.", o = { "کشته شدن Invasive Drifter" }, p = "...", c = "وقتش رسیده جای خودت را میان مردم ما بگیری و ماجراجویی‌های بچگانه را کنار بگذاری. از راهنمایی من پیروی کن و Aln'hara این روز را مبارک کند.\n\nیادت باشد، سنت‌های ما راه را به ما نشان می‌دهند." }
WoWFQ[90958] = { t = "ریشه‌ها فراتر از همه", d = "بعضی می‌گویند درختان بزرگ خودشان رشد می‌کنند و Harandar حتی بی‌مراقبت ما برجا می‌ماند. سنت‌های ما می‌گویند: فرقی نمی‌کند. ما اینجاییم تا محافظت کنیم، مراقبت کنیم و خدمت کنیم. با وقف و تواضع.\n\nتمیز نگه‌داشتن محیط اطراف ریشه‌ها و پاک نگه‌داشتن‌شان از آفت، بازتاب همین وظیفه است. وقتی تمام شد پیش من برگرد. راه ما را خوب نمایندگی خواهی کرد، <name>.", o = { "پاک شدن آفت‌ها", "بررسی صدای مرموز" }, p = "تکالیفی که از تو خواسته بودم را انجام دادی؟", c = "این مال غریبه‌هاست؟ تو به‌جای انجام وظایفت، مشغول کمک به Orweyna با همین... سرگرمی‌ها بودی. اگر در مراسم هم از راهنمایی من پیروی نکنی، چطور می‌خواهی از سنت‌های ما محافظت کنی؟\n\nبا Hagar بزرگ صحبت خواهم کرد. اهمیت این روز و وظیفه‌ات را به یاد داشته باش." }
WoWFQ[90959] = { t = "وظایف سنتی", d = "Dalnir دربارهٔ مراسم حرفش بجاست، اما نباید تونل‌بینی کنیم. من به ارزش‌های مردم‌مان پایبندم، اما گاهی باید فراتر از آن‌ها را هم دید.\n\nنگران نباش. تو باید حواست به مراسم باشد. بعداً خودم دنبال غریبه‌ها می‌گردم.\n\nمطمئنم بعد از تمام شدن آیین ورود، می‌توانی به من بپیوندی.", o = { "دیدار با Dalnir در Den of Remembrance", "پیدا شدن غریبه", "نجات غریبه", "رساندن غریبه به امنیت" }, c = "غریبه از کارهای تو برایمان گفت.\n\nباید بفهمی، <name>، هرچند شجاعانه بود، خطرناک هم بود؛ حتی برای تو.\n\nمی‌دانم Dalnir عصبانی است، اما Hagar میل تو به کمک را می‌فهمد." }
WoWFQ[90960] = { t = "قصهٔ من، میراث من", d = "<name>، بخش واپسین مراسم پیش روی توست، هرچند با سرگردانی‌هایت آن را به خطر انداختی.\n\nمجسمهٔ اول تصویری از خودِ راستینت به تو نشان می‌دهد، همان که از درونت طنین‌انداز است.\n\nمجسمهٔ دوم تصویری از جایی نشان می‌دهد که به تو نیاز است.\n\nسنت می‌گوید مجسمهٔ سوم، پردهٔ میان ما و خود Goddess را می‌شکند.\n\nمراسم با نقاشی کردن قصهٔ تو در Den به پایان می‌رسد.", o = { "بازدید Legacy Stone of True Self", "بازدید Legacy Stone of True Calling", "بازدید Legacy Stone of the Goddess Guidance", "با Hagar صحبت کن", "نقاشی Legacy Stone" }, p = "با طمأنینه پیش برو، <name>. مراسم به سرعتش نیست، به آموخته‌ای است که از آن می‌گیری.", c = "در همهٔ این سال‌های آیین‌ها، این اولین بار است. به نظر می‌رسد خودِ Goddess به تو توجه کرده است.\n\nسفری مرموز و پرنوش در پیش رویت حس می‌کنم." }
WoWFQ[90961] = { t = "غریبه‌ای در سرزمینی نو", d = "<name>، حالا می‌بینم که هستی. وقف تو فقط به مردم ما نیست، به همهٔ دنیاست.\n\nGoddess هم تو را تصدیق کرده، و من چنین رویدادی را به یاد ندارم -- حتی مراسم Orweyna این‌قدر پرحادثه نبود.\n\nاین‌جا جایی است که قصهٔ تو آغاز می‌شود. وقتش است نخستین قدم‌های سفرت را برداری.", o = { "با Hagar دربارهٔ مراسم صحبت کن", "ورود به rootway" }, c = "پس تو <name> هستی؟\n\nفکر نمی‌کردم یک haranir به این شهر سر بزند. با همین حال، کارهایت پیشاپیش برایم آشناست.\n\nچند قلم تجهیزات پایه برایت آماده کرده‌ام. دست‌کم کاری است که می‌توانم بکنم برای کسی که یکی از ما را نجات داد." }
WoWFQ[90963] = { t = "غارهای Cleft", d = "برای آزاد کردن rutaani‌های اسیر، کار خوبی انجام دادی. با دانه‌هایی که بازیابی کردی، می‌توانم کار Ru'gar را ادامه بدهم.\n\nوقتی تو حواس fungarian‌ها را پرت می‌کردی، من کمی گشت‌زنی و جمع‌آوری کردم، و برای یک کار دیگر به کمک تو نیاز دارم. در غار سمت شمال‌شرق همین‌جا به من ملحق شو.", c = "به نظر می‌رسد این جایی امن برای طرح‌ریزی حرکت‌های بعدی‌مان باشد، و یکی از گیاهانی که Ru'gar به من گفته بود هم در این ناحیه می‌روید." }
WoWFQ[91063] = { t = "The Blooming Lattice", d = "تو همان غریبه‌ای هستی که درباره‌اش شنیده‌ام، مگر نه؟ من Su'meera هستم، شاگرد نقاش Ja'kul. اسمش را شنیده‌ای؟ نه؟ شاید کارهایش به سرزمین‌های تو نرسیده باشد. طبیعی است دیگر، حدس می‌زنم.\n\nراستش، شنیده‌ام که از کمک به دیگران خوشت می‌آید. خب، وقتی Ja'kul مورد حمله قرار گرفت و کشته شد، چند چیز مهم گم شد. من آن‌ها را پس می‌خواهم.\n\nنزدیک Blooming Lattice به من ملحق می‌شوی؟", c = "ممنون که آمدی. مطمئن نبودم که بیایی. بالای تپه، آن سمت، Blooming Lattice است؛ سکونتگاهی از rutaani که به‌شدت خشن‌اند.\n\nرهبرانشان Ja'kul را کشتند و وسایلش را بردند. من آن‌ها را پس می‌خواهم!" }
WoWFQ[91065] = { t = "ربودن گلبرگ‌ها", d = "چند روز پیش، گروهی از rutaani به استادم Ja'kul حمله کردند و او را کشتند. در حین حمله، پرنده‌های احمقشان چند چیز از او دزدیدند. این گلبرگ‌مغزها هر چیز براقی را که با خار محکم نشده باشد می‌ربایند.\n\nمی‌شود وسایل Ja'kul را برایم بازیابی کنی؟ من نقاشم، نه جنگجو. به‌تنهایی آنجا زیاد دوام نمی‌آورم.", o = { "اشیای دزدیده‌شده را از Blooming Terrace بازیابی کن.", "Well-Worn Ladle", "Pilfered Crafting Drill", "Splattered Scroll", "Paint-Speckled Gourd" }, p = "آن پرنده‌ها اگر سرت به شانه‌هایت وصل نبود، همان سرت را هم می‌دزدیدند. مخصوصاً اگر کلاه یا کلاه‌خود براقی بر سر داشته باشی. درست از روی شانه‌هایت!\n\n<او لحظه‌ای مکث می‌کند، انگار که این صحنه را در ذهنش مجسم می‌شود؛ سپس رنگش کمی سبز می‌شود و می‌لرزد.>", c = "انجامش دادی! می‌دانستم اینها را دارند، آن لاشخورهای علف‌مغزِ گندیده!\n\nمی‌دانم خنده‌دار است که آدم برای چیزهایی مثل قاشق محبوبش ناراحت شود، اما آنها زندگی Ja'kul را گرفتند. اجازه نمی‌دهم چیز دیگری از او بگیرند.\n\nتو بهترینی، <name>." }
WoWFQ[91085] = { t = "تارهای گلبرگی", d = "Ja'kul رفته بود شکار petalwing کند که rutaani سرِ راهش رسیدند و کشتندش. ما از پرهایشان برای برخی از قلم‌موهامان استفاده می‌کنیم. به‌خصوص در کمک به جوانه‌های کوچک سودمندند تا یاد بگیرند چگونه دقیق‌تر و ظریف‌تر کار کنند.\n\nحالا که آن بالا می‌روی، می‌شود چندتا از پرهایشان را برایم بیاوری؟", o = { "8 Petalwing Plume جمع‌آوری کن.", "Petalwing Plume" }, p = "پرهای petalwing را که خواسته بودم جمع کرده‌ای؟ برای درس‌های جوانان haranir ضروری‌اند.", c = "ممنونم که این پرها را برایم آوردی! از یکی از آنها برای کشیدن یادبودی خاص برای Ja'kul استفاده خواهم کرد. بقیه هم به بچه‌ها می‌رسد.\n\nفکر می‌کنم حالا نوبت من است که به آنها آموزش بدهم." }
WoWFQ[91086] = { t = "جوانه‌کشی", d = "Rutaaniهای Blooming Lattice پشت یورش به Ja'kul بودند. رهبرشان Prime Bloomwarden‌ای است که حتی بی‌رحم‌تر است. ازشان متنفرم و همه‌شان موجودهای رذلی‌اند!\n\nتو برو این روییدگی هرز را هرس کن و بقیه‌مان را امن‌تر کن، چطور؟", o = { "Rutaani کشته شدند (12)", "Prime Bloodwarden Kazat کشته شد" }, p = "Rutaaniها معمولاً این‌قدر خشن نیستند. Ja'kul قبلاً می‌گفت دلیلش این است که روستایشان را خیلی نزدیک fungarianهای Fungal Cleft ساخته‌اند.\n\nبا آن جوانه‌سرها کارت را تمام کردی؟", c = "تمامش کردی؟ ممنونم. Ja'kul را برنمی‌گرداند، اما دیگر کسی را اذیت نمی‌کنند." }
WoWFQ[91088] = { t = "پشت آبشار", d = "طوماری که برگرداندی، استادم Ja'kul برای من باقی گذاشته بود. حتی فرصتی برای خواندنش پیدا نکردم که دزدیده شد!\n\nJa'kul در طومار، راه رسیدن به غاری را نشان داده که پشت آبشاری در Blooming Lattice قرار دارد. مطمئن نیستم آنجا چه چیزی پیدا خواهیم کرد، اما واقعاً خوشحال می‌شوم اگر در بررسی‌ام همراهم باشی. آنجا به من می‌پیوندی؟", c = "این شگفت‌انگیز است! باورم نمی‌شود اینجا پشت، یک غار کامل وجود دارد. و Ja'kul یک سنگ بینش برایم گذاشته است." }
WoWFQ[91136] = { t = "خاطراتی در سنگ", d = "Ja'kul را پیش از آنکه آموزشم را کامل کند کشتند، اما کارش را هر جا باشد می‌شناسم! قطعاً این سنگ بینش را برای من نقاشی کرده است!\n\nrutaani خیلی زود می‌فهمند که ما این بالاییم، و من نمی‌توانم از خودم دفاع کنم. در حالی که من به خاطره‌ای که برایم باقی گذاشته سفر می‌کنم، مراقبت می‌کنی؟", o = { "در حالی که Su'meera سفر بینش می‌کند، از او دفاع کن.", "با Su'meera صحبت کن", "از Su'meera دفاع شد" }, c = "خیلی ممنونم، <name>. راهی برای خداحافظی با استادم به من دادی. حالا که آنچه را او می‌خواست دیده‌ام، می‌توانم آموزشم را ادامه دهم.\n\nبرایم بسیار ارزشمند است که Ja'kul این را برایم اینجا گذاشته. دلم برایش تنگ شده، اما یادش را گرامی خواهم داشت." }
WoWFQ[91270] = { t = "مهم‌ترین چیز", d = "برای Pit قوی خواهیم بود!\n\nاما Boletus حق دارد. چیز دیگری لازم است. باید اسم عالی داشته باشیم.\n\nتیم‌های بهترین همه اسم خوب دارند. Fungus Force. Spore Storm. Cap Clash. و قهرمان‌ها، Glow Guard!\n\nهمه اسم‌های خوبی‌اند.\n\nاسم شگفت‌انگیزی لازم داریم. بهترین اسم. تا بهترین تیم شویم.\n\nدر انتخاب کمک می‌کنی؟", o = { "برای انتخاب اسم با تک‌تک هم‌تیمی‌هایت صحبت کن.", "با Brakko مشورت شد", "با Ziny مشورت شد", "با Tuktuk مشورت شد", "اسم تیم انتخاب شد" }, p = "بهترین اسم را پیدا کردی؟", c = "Fungal Fell...owship، قبول. حالا آماده‌ایم.\n\nهمگی با هم وارد Pit می‌شویم، شعار Fungal Fello...sip را سر می‌دهیم، اِه...\n\nجمعیت تشویق خواهد کرد، بعد قهرمانان جدید می‌شویم!" }
WoWFQ[91346] = { t = "توسل‌جویان به الهه", d = "ما مدت‌های طولانی است که با کمک موجوداتی که اینجا زندگی می‌کنند و رشد می‌کنند، از ریشه‌ها نگهداری می‌کنیم. این رابطه‌ای هم‌زیستی است که ما، موجودات و ریشه‌ها همه از آن سود می‌بریم. با این حال، شریکم Riverscale این اواخر خیلی همکاری نمی‌کند!\n\nلطفاً کمکم کنید راهی برای برانگیختن دوباره او پیدا کنم.\n\nاول، باید جوهر دنیای بیرون را از خودت بشویی. خودت را در آب‌های Har'kuai تطهیر کن.", o = { "خودت را در Waters of Har'kuai پاک کن.", "با Waters of Har'kuai تعامل کن", "Waters of Har'kuai کشته شد" }, c = "شاید بی‌اهمیت به نظر برسد، اما همه‌اش بخشی از روند است." }
WoWFQ[91359] = { t = "قارچ‌تازان، بروید گم شوید", d = "اینکه در Harandar زندگی می‌کنیم نعمتی است، اما در همان حال مسئولیت ما هم هست. ریشه‌های درختان جهان از میان این سرزمین‌ها می‌پیچند. ما از آنها نگهداری می‌کنیم و آنها هم شکوفا می‌شوند. به همین دلیل است که بازگشت Riverscale به وظیفه‌اش این‌قدر مهم است.\n\nباید این زمین‌ها را پیش از آنکه قارچ‌تازان شیره ریشه‌ها را بمکنند، پاک نگه داریم. به‌علاوه، Riverscale واقعاً عاشق سرشاخه‌های قارچ‌تازهاست. می‌توانی چندتا برایش پیدا کنی و بیاوری؟", o = { "6 Harmonious Fronds را در حاشیه‌های Har'kuai جمع‌آوری کن.", "Harmonious Lash" }, p = "مهم است که نگذاریم قارچ‌تازها مواد مغذی مهم درخت جهان را بمکنند.\n\n...و من دوست دارم پسر کوچک لجبازم را لوس کنم.", c = "کاش تنبل‌ترین کمک‌کار تاریخ کمک‌کارها را نداشتم، اما زندگی همین است!\n\nاگر خوراکی‌های محبوبش هم بلندش نکنند، دیگر هیچ‌چیز بلندش نخواهد کرد." }
WoWFQ[91375] = { t = "سکوت در روستای Fungara", d = "روستای Fungara مدتی است ساکت شده.\n\nبیشترِ حواس‌مان معطوف به Lightbloom و تهدیدش بود، پس فرصت نکردیم سر بزنیم به fungarianهای شرق. معمولاً پرسر و صدا هستند اما در کنترل‌اند... اما سکوت کامل‌شان کم‌سابقه است.\n\nGhikal، یکی از شکارچیان‌مان، زودتر رفته بررسی کند. اگر می‌خواهی ثابت کنی متحدی، خوب است دست او را بگیری.", o = { "بیرون روستای Fungara در Harandar دنبال Ghikal بگرد." }, c = "معمولاً بدون معطلی مداخلهٔ یک غریبه را رد می‌کردم... اما با این وضعیت، شاید کمکی از دستت بربیاید." }
WoWFQ[91376] = { t = "هیولاهای کوچک", d = "وقتی از Har'alnor تقاضای کمک کردم، انتظار نداشتم برایم غریبه‌ای بفرستند. بگذریم.\n\nساکنان روستای Fungara ساکت شده‌اند. معمولاً از این حالم می‌گیرد؛ به‌طرز وحشتناکی جیغ‌جیغو هستند. اما این‌طور که می‌لنگانند این‌ور و آن‌ور... انگار فراموش کرده‌اند هنوز زنده‌اند.\n\n<Ghikal shudders.>\n\nسعی کردم نزدیک شوم، اما همان‌جا که مرا دیدند حمله کردند.\n\nبه نمونه‌هایی از گوشت‌شان نیاز دارم. برو و برایم بیاور تا ببینم اینجا چه خبر است.", o = { "میسلیوم عجیب" }, p = "نمی‌دانم چه خبر است، اما برای محکم‌کاری... بگذار گازت نگیرند، خوب؟ هر بلایی سرشان آمده شاید مسری باشد.", c = "Goddess حفظمان کند. این اصلاً گوشت fungarian نیست.\n\nاین‌ها دیگر چه هستند؟" }
WoWFQ[91377] = { t = "زادهٔ مردگان", d = "واضح است که در روستا فاجعه‌ای رخ داده. از همین‌جا جنازهٔ بزرگ‌ترین نمونه‌هایشان را در دامنه‌های جنوبی می‌بینم که افتاده‌اند. اما در آنها هم چیزی ناجور است. fungarianها معمولاً جنازهٔ هم‌نوعانشان را ول نمی‌کنند آنجا.\n\nو هرچند از دور تماشا می‌کنم، قسم می‌خورم بعضی‌شان دارد... تکان می‌خورند.\n\nبررسی کن. هر چه می‌توانی دربیاور و پیش من برگرد گزارش بده.", o = { "بررسی جنازه‌های شکوفا" }, p = "...", c = "این خیلی بدتر از تصورم است.\n\nباید منبع این ماجرا را پیدا و نابود کنیم قبل از اینکه چیزی بزرگ‌تر و خطرناک‌تر از یک fungarian را آلوده کند." }
WoWFQ[91490] = { t = "خاموش کردن آتش Teldrassil", d = "ریشه‌های Teldrassil امروز دود می‌کنند. به آسمان برو و شعله‌ها را خاموش کن.", o = { "خاموش شدن آتش‌های دودکن" }, c = "ممنونم. امید که روزی همهٔ آتش باقی‌ماندهٔ درخت را فرو بنشانیم و رشد تازه‌ای جوانه بزند." }
WoWFQ[91550] = { t = "بازی سکوت و سایه", d = "تو فرق داری! این هم باحالیت دارد... هم خیلی مشکوک می‌کنی. می‌خواهیم ببینیم از چه قراری هستی!\n\nپس این بازی: ما قایم می‌شویم، تو سعی می‌کنی پیدامان کنی. اگر پیدا کردی، خب... معلوم می‌شود برای دفعهٔ بعد باید بیشتر تمرین کنیم. اما اگر پیدا نکردی؟ شاید آن‌وقت پدر و مادرها بالاخره بگذارند اولین شکارِ تک‌نفره‌مان را برویم!\n\nاین یک بازی مسخره نیست، بشنو؟ یک آزمون است به نام سکوت و سایه. جدی است. خیلی، خیلی جدی.\n\nآماده‌ای؟", o = { "با Shao'mal صحبت کن", "انتظار برای قایم شدن بچه‌ها", "پیدا شدن بچه‌ها" }, p = "...", c = "آن petalwing هیولایی بردش! و ما ایستادیم... مثل قارچ منجمد!\n\n<Ilomai shakes her head and gathers her resolve.>\n\nوقتی برای ترسیدن نداریم. حرکت می‌کنیم. همین حالا." }
WoWFQ[91553] = { t = "haranir هرگز نمی‌میرد!", d = "همین است! همان بزرگ! همان که بردش!\n\nقبل‌ها نتوانستیم جلویش را بگیریم. اما این بار می‌گیریم. ما haranir هستیم. و haranir هرگز عقب‌نشینی نمی‌کند. haranir هرگز تسلیم نمی‌شود.\n\nبرش می‌گردانیم. و به این ماجرا پایان می‌دهیم. همراهم هستی؟", o = { "کشته شدن Behemoth Petalwing" }, c = "خیلی ممنون بابت نجاتم... البته که نیازش را نداشتم. به هر حال، خودت هم به‌ظرخی خوبی. بعد از صحبت با همه، همه موافقت کردیم که جزو گروه‌مان شوی!\n\nبه خودت افتخار کن. این افتخاری است که به‌ندرت نصیب کسی می‌شود، اما هر ذره‌اش را درخوردی. رسماً یکی از ما شدی! سرت را بالا بگیر، قدت را راست کن، و هرگز تسلیم نشو!" }
WoWFQ[91555] = { t = "مدافعان دره", d = "مدافعان دره از پا افتاده‌اند. با این گردهٔ جان‌بخش آن‌ها را سرپا کن.", o = { "جان گرفتن مدافعان خسته" }, c = "خوب بود. با انرژی از نو، سر کارشان برمی‌گردند." }
WoWFQ[91582] = { t = "هرس شبکه", d = "این rutaaniهای درنده روی Blooming Lattice سبز شده‌اند. هرس‌شان کن.", o = { "هرس شدن Blooming Lattice" }, c = "امید که دیگر به مناطق دیگر سرریز نشوند و تهدیدی نباشند." }
WoWFQ[91585] = { t = "تازه از دل باغ", d = "امروز صبح پیری به سرم افتاد و کاری از کارم درآمد.\n\n<Yu'relen clutches his back.>\n\nبا این حال، غذای روستایی باید آماده شود. وگرنه بهای بیشتری از یک دل گرسنه خواهیم داد.\n\nاگر لطف کنی چند قلم مواد برای غذا جمع کنی، زحمتت بی‌جواب نمی‌ماند.", o = { "فیلهٔ Frillfish", "ژلهٔ Root Drift", "نوشیدن معجون Yu'relen" }, p = "امید که برداشت خوبی با خودت آورده باشی.", c = "عالی است. حتی سرآشپز پیر هم با دست‌های زبرسته در کنارش، معجزه می‌کند." }
WoWFQ[91586] = { t = "جایگزین‌های خاکی", d = "این غذا فقط سنت نیست؛ یک قول است.\n\nHaranir و Rutaani و Fungarianها همدیگر را دوست ندارند، اما در Har'mara پشت همین میز مشترک‌اند. برای گرامی‌داشت این پیمان، هر یک باید به شیوهٔ خودش سیر شود. این معنای این غذاست.\n\nبرای Rutaaniها، خاکِ سرشار از مواد مغذی لازم است چون از ریشه‌هایشان تغذیه می‌کنند. چند کیسه کافی است.", o = { "خاک سرشار از مواد مغذی" }, p = "امید که خبر خاک خوبی آورده باشی.", c = "خوب است. rutaaniها بی‌گله قبولش می‌کنند. صلح بر پایهٔ همین حرکت‌ها استوار است." }
WoWFQ[91587] = { t = "آشپزی با لاشه", d = "Fungarianها پرستارِ پوسیدگی‌اند؛ مرگ را به رشد دوبارهٔ زندگی بدل می‌کنند.\n\nبرای سیر کردن جامعهٔ بزرگشان به لاشهٔ sporeglider نیاز دارند. یکی هست--بزرگ‌تر از بقیه--که دنبال راندن root drifterهایی است که روستای ما به آن‌ها نیاز دارد.\n\nپایان کارش خیلی‌ها را سیر می‌کند و بار از دوش‌مان برمی‌دارد. توازن، از بیش از یک جهت.", o = { "کشته شدن Sporeglider Bloomterror", "پوست لاشه" }, p = "پوست را آوردی؟", c = "این لاشه هم نوازش تازه‌ای به سفرهٔ fungarianها می‌زند، هم به صلحی که پاس می‌داریم." }
WoWFQ[91785] = { t = "افسون‌هاگ‌زده", d = "هاگ‌های Lightbloom از The Blinding Bloom سرریز می‌شوند. قبل از پخش شدن، ریشه‌کن‌شان کن.", o = { "کشته شدن هاگ‌های Lightbloom" }, c = "خوب بود. شاید این نبرد مدت‌ها طول بکشد، اما کمکی به مهار سیلش کردی." }
WoWFQ[91872] = { t = "Rootwarden پیشین", d = "<name>، من Rootwarden خودِ Teldrassil بودم. سال‌ها ریشه‌های اینجا را زیر سطح زمین زیر نظر داشتم، اما از تهدیدی که بیرون از Harandar درخت را تهدید می‌کرد بی‌خبر بودم.\n\nبه همان اندازه، از آن شکست پشیمانم، اما گذشته را نمی‌شود عوض کرد.\n\nبا این حال حیرت می‌کنم: مگر ریشه‌هایی به این عظمت واقعاً به‌کلی مرده‌اند؟ شاید هنوز کاری بتوان کرد؟\n\nنمی‌دانم، اما امید دارم. به Shrine of Ages می‌آیی تا در مراقبت از ریشه‌ها همراهی‌ام کنی؟", o = { "در Shrine of Ages به Hagar بپیوند." }, c = "خیلی بیشتر از سال‌هایی که Rootwarden شدم، قبلش زندگی کرده‌ام.\n\nبا این حال Teldrassil همیشه همان چیزی خواهد بود که زندگی‌ام را تعریف می‌کند." }
WoWFQ[91873] = { t = "منطقهٔ حائل", d = "در این زیارتگاه، دنبال ریشه‌هایی گشته‌ام که هنوز نشانه‌هایی از زندگی در آن‌هاست. هر کدام آسیب دیده‌اند؛ بعضی بیشتر، بعضی کمتر. امید دارم با وقت کافی و مراقبت کافی، بعضی‌شان بازیابند. این‌طور، یاد بزرگ‌ترین درخت را گرامی می‌دارم.\n\nبرای اینکه این ممکن شود، اما باید از خطرهای Harandar در امانشان بداریم.\n\nحواست باشد هیچ چیز از آن اطراف تهدیدشان نکند.", o = { "محافظت از زیارتگاه" }, c = "ممنون بابت محافظت از هر آنچه شاید هنوز از Teldrassil زنده باشد.\n\nشاید هیچ چیز باقی نمانده باشد--بعضی از این ریشه‌ها هنوز دود می‌کنند.\n\nبا این حال سوگند خورده‌ام Rootwarden باشم، و بار دوم شکست نمی‌خورم، اگر ذره‌ای امید باشد. هر روز برمی‌گزینم که باور کنم شاید بشود، که Teldrassil دوباره شکوفا شود.\n\nهرچند شاید فقط دارم یادش را نگه می‌دارم." }
WoWFQ[91874] = { t = "شعله‌ور شدن دوباره", d = "<name>، دود از بالای Har'mara برمی‌خیزد. ریشه‌ها آتش گرفته‌اند--نه اینجا، بلکه زیر باقی‌ماندهٔ درخت!\n\nاین را بارها دیده‌ام، اما همیشه باید فوراً پاسخ داد.\n\nبه آسمان بزن و همین حالا خاموششان کن!", o = { "خاموش شدن آتش‌های دودکن" }, c = "<name>، بوی دود همان وحشت روز هولناک را در من زنده می‌کند.\n\nگرمای زیادی هنوز در بزرگ‌ترین ریشه‌ها حبس است، و با شرایط درست، آتش از نو شعله می‌کشد.\n\nاگر امیدی داریم که روزی ریشه‌ها بازیابند، باید حتی آتش کوچک را جدی بگیریم." }
WoWFQ[91875] = { t = "درمان طبیعی", d = "اگر می‌خواهیم آن آتش‌ها برای همیشه خاموش شوند یا رشد تازه‌ای ببینیم، ریشه‌های Teldrassil به توجه ویژه‌ای فراوان نیاز دارند.\n\nسرچشمهٔ جوی یکی از ریشه‌های بزرگ است. آب خاکستر با خود می‌برد که باور دارم هنوز جوهرِ درخت را در خود دارد.\n\nstalkerهای جوی آمیزه‌ای از همان خاکستر و لجن شاخک‌هایشان با خود دارند--ترکیبی بسیار قدرتمند.\n\nهر چه می‌توانی حمل کنی برایم بیاور، و با مواد واکنشی‌ای که جمع کرده‌ام ترکیبش می‌کنم. بعد آمادهٔ مالیدنش به ریشه‌ها هستیم.", o = { "لجن Verdant Stalker" }, p = "آن لجن جان‌بخشی که خواستم را آورده‌ای؟", c = "برای امروز، همین به کار می‌آید. یک لحظه تا با این مواد واکنشی ترکیبش کنم." }
WoWFQ[91876] = { t = "مراقبت از امید", d = "از آن لجن مرهمی برای Teldrassil ساخته‌ام، <name>. حالا باید روی ریشه‌های اینجا بمالیم.\n\nشاید سال‌ها طول بکشد تا فرقی ببینیم، اگر اصلاً ببینیم. اما... با اینکه شکست خوردم، هنوز به او سوگند بسته‌ام، و هنوز می‌توانم انتخاب کنم به‌شان وفادار بمانم. هرگز دست از آنچه از دستم برمی‌آید برنمی‌دارم تا... شاید دوباره رشد کند.\n\nحتی اگر موفق نشوم، شاید Rootwarden بعدی، یا یکی که بعد از او بیاید، این کار را تمام کند. با این حال، دست نمی‌کشم.", o = { "مالیده شدن مرهم Hagar" }, c = "ممنون بابت کمکت، <name>.\n\nبه لطف تو توانستم با وجود آن آتش‌ها، به کارهای همیشگی‌ام ادامه دهم.\n\nشاید یک روز، جوانه‌ای ببینیم--هرچند سال‌ها طول بکشد.\n\nو من همیشه آمادهٔ از سر گرفتن وظیفه‌ام به‌عنوان Rootwarden خواهم بود، اگر امید شکوفا شد." }
