WoWFQ[91998] = { t = "مطلوب است: پیچک‌های خفه‌کنندهٔ Muckmire", d = "در عمق باتلاق، موجودی است از گِل، برگ و خشم. پیچک‌هایش جان هر که نزدیک شود را خفه می‌کند، و این موجود خطرناک نباید زنده بماند.\n\nMuckmire را شکست بده و پیچک‌هایش را به‌عنوان مدرک کار برایم بیاور.", o = { "پیچک خفه‌کننده", "پیشنهاد بازیکنان: 3" }, p = "حواست باشد Muckmire نکشدت با خودش به ته گِل نکشد.", c = "درست مثل یک موجود گِلی و کثیف به نظر می‌رسی. انجامش دادی؟\n\nآه بله، این پیچک‌های او هستند. آفرین." }
