WoWFQ[92559] = { t = "قدردانی از شعله", d = "فصل نیم‌تیرماه شاید برایمان ناآشنا باشد، اما قصه‌گفتن در نور شعله‌های ریشه‌ای‌مان آشناست.\n\nلحظه‌ای کنار آتش‌باز بیندیش، دوست من، و به اطرافیانت گوش بسپار.\n\nدر آنچه پیش از تو گذشت و آنچه هنوز نیامده تأمل کن.", o = { "قدردانی از آتش‌باز نیم‌تیرماه در Harandar." }, c = "قدردانی از شعلهٔ Harandar." }
