WoWFQ[92694] = { t = "غروب میان رنگ‌ها", d = "ما Zur'asharها سوگند خورده‌ایم از هماهنگی درون رؤیاواه‌ها و تاریخ‌هایی که ثبت می‌کنیم محافظت کنیم.\n\nاما خط‌های خام Orn'shan بی‌احتیاط‌اند. تکانه‌های خلاقانه‌شان رشد نیافته و به توازنی که سوگند از آن پاسداری کنیم لطمه می‌زند. در تلاشی گمراهانه برای خلاقیت، آشوبی مهارناک پا کرده‌اند و دارند حقیقت‌هایی را که می‌خواستند ثبت کنند از شکل می‌اندازند.\n\nشاید پیش از آنکه اعتبارش به‌کلی بریزد، حرف یک غریبه را بشنود.", o = { "در Amirdrassil Roots با Orn'shan صحبت کن." }, p = "...", c = "آمدی مسخره‌ام کنی تو هم؟" }
WoWFQ[92739] = { t = "شکوفه‌کنندهٔ بی‌تعارف", d = "آشیانهٔ موجودی زیرک را یافته‌ام که اسمش را گذاشته‌ام Adzikel. با شانس، این اسم به‌زودی فراموش می‌شود.\n\nAdzikel به لانه‌های potatoad قاپ می‌زند و بچه‌هایشان را می‌دزدد، و هاگ‌های Lightbloom می‌کارد تا رشدشان را به toadهای دیوانه تند کند که خودشان هاگ بیشتری می‌پراکنند.\n\nبرای اینکه بچه‌ها شانسی داشته باشند، باید به Har'alnor برگردم، اما تو حق داری این جانور را بکشی. با افتخار برو و شکار را تمام کن!", o = { "کشته شدن Adzikel" }, p = "Adzikel کشته شد؟", c = "Lightbloom سرسخت است، اما تو هم سرسخت‌تری. سرزمین‌ها و جانداران Aln'hara به لطف زحمت تو برجا مانده‌اند.\n\nبچه‌ها را به زیستگاه طبیعی‌شان پس می‌برند، از هاگ‌ها پاک--همه‌شان جز این یکی. برای تنهایی در طبیعت خیلی کوچک است.\n\nبه مراقب نیاز دارد، و به نظرم به تو دلبسته شده است." }
WoWFQ[92864] = { t = "پس راندن drifterها", d = "قبل از اینکه orchid hydraها شکار و از Jungle Cascades رانده شوند، گیاهان و جانوران بومی را در کنترل داشتند.\n\nبدون hydraها، جمعیت drifterها زیاد شد و تهدیدی جدی گشت. خیلی از جانوران دیگر نمی‌توانند به آبشارهای پایینی نزدیک شوند چون کیسه‌تخم‌های انبوه drifterها آب را گِل و غیرقابل نوشیدن کرده است.\n\nکم کردن شمار drifterها و نابود کردن بعضی لانه‌ها، به hydraها سر آغاز خوبی می‌دهد تا جمعیت drifterها به حالت عادی برگردد.", o = { "کشته شدن Cascade Drifter", "برداشتن کیسه‌تخم drifterها" }, p = "...", c = "کم کردن جمعیت drifterها دلم را می‌لرزاند. اما اگر مهار نمی‌شدند، شمارشان اکوسیستم را فروریخته می‌کرد." }
WoWFQ[92865] = { t = "سیر کردن جوانه‌ها", d = "غذای مورد علاقهٔ orchid hydra، chloroceros شاخ‌بنفش است--مخصوصاً جوانه‌های روی پشت گاو نر.\n\nبا غیبت طولانی hydraها، chloroceros شاخ‌بنفش از مرز چریدن گذشت و به‌زودی آن بخش سرسبز و زیبای Harandar چیزی جز گِل نخواهد بود.\n\nمی‌خواهم hydraهایم را با منبع اصلی غذایشان آشنا کنم، و ممنون می‌شوم اگر چهار تا از آن جوانه‌ها را برایم بیاوری.", o = { "جمع‌آوری جوانهٔ Chloroceros", "سیر کردن Grumpy", "سیر کردن F'liks", "سیر کردن T'omm", "سیر کردن N'ala" }, p = "جوانه‌های عزیز با اولین چشیدن جوانه‌های chloroceros خیلی خوشحال می‌شوند.", c = "جوانه‌ها فعلاً سیر به نظر می‌رسند. با خیال راحت به فاز دومِ بازگرداندن‌شان به زیستگاه طبیعی می‌رویم." }
WoWFQ[92882] = { t = "دردِ یک شکارچی", d = "تو را این‌ور و آن‌ور دیده‌ام و به نظر می‌رسد کسی هستی که شکار را بلد است.\n\nمی‌خواهم به Ka'shuk بپیوندم، گروهی نخبه از شکارچیان. برای این کار به استاد نیاز دارم. هر Ka'shuk حاضر در هر دوره فقط یک شاگرد می‌گیرد، و دیگر Ka'shuk استادی باقی نمانده.\n\nشاید زیادی طلبم، اما حاضر هستی استاد من شوی؟ می‌توانم با Akazi، بزرگ Ka'shuk حرف بزنم. اگر قبول کنی البته.", o = { "با Elder Akazi دربارهٔ آزمون‌های Ka'shuk صحبت کن." }, p = "Ketan به من می‌گوید می‌خواهی استادش شوی. درست است؟", c = "برکت من با توست، <name>. هرچند Ka'dani نیستی، داستان‌های توانایی‌ات پیشاپیش به گوشم رسیده. مهارت‌هایت در شکار نیاز به معرفی ندارند.\n\nمی‌دانم می‌توانی راهنمایی‌ای که Ketan نیاز دارد به او بدهی.\n\nهر دو در آزمون‌های Ka'dani شرکت می‌کنید: تو به‌عنوان Ka'dani افتخاری، و Ketan به‌عنوان شاگرد تو." }
WoWFQ[92883] = { t = "وظیفهٔ یک شکارچی", d = "در آغاز آزمون، استاد و شاگرد مواد لازم برای آهنگری سلاح شکار را جمع می‌کنند.\n\nاین سلاح فقط امتداد دست Ka'dani نیست--بخشی از وجودش است. سلاحی مثل آن دومی ندارد، چون هر یک یگانه است.\n\nبه Ketan کمک کن شکار کند و مواد و تزئینات، به‌علاوه هدیه‌ای برای زره‌ساز، جمع کند.", o = { "استخوان Chloroceros", "دندان Grovecrawler", "Lasher Vine (quest item)", "هاگ دمی Sporeglider", "پیدا شدن Ketan در حین شکار", "Lasherها", "Chloroceros" }, p = "همه چیز را پیدا کردی؟ می‌دانم بعضی از این مواد به‌سختی جمع می‌شوند.", c = "به نظر بی‌نقص می‌آیند.\n\nممنون که این را برایم کردی. شاید یک روز بتوانم همین را برای کسی دیگر بکنم." }
WoWFQ[92885] = { t = "شکارِ یک شکارچی", d = "آزمون واپسین پیش روی شماست. با هم سلاحی آهنگری کردید که هر جانوری را از پا درمی‌آورد، اما سلاح بدون شکارچی هیچ است.\n\nچون تو Ka'dani نیستی، شکاری دشوار پیشنهاد می‌کنم. Ketan و تو شکارچیانی را از پا درآورید که همهٔ شکارچیان Har'athir می‌شناسندش: Radooni بزرگ. این جانور خیلی به Har'athir نزدیک شده و شکار مناسبی خواهد بود.\n\nوقتی شکار تمام شد و شیرهٔ Radooni روی نیزه نشست، پیش من برگرد.", o = { "پیدا کردن Ketan بیرون Har'athir", "کشته شدن Radooni" }, p = "...", c = "حالا می‌بینم که حضور تو اینجا و پشتکار Ketan، به دست خود Goddess چیده شده بود. از کردار و اراده‌ات تحت تأثیر هستم. به لطف تو، راه Ketan روشن است." }
WoWFQ[92899] = { t = "درس تاریخ", d = "Hagar خواسته همهٔ رهبران ترول و الف‌هایی که می‌شناسیم به این جلسه دعوت شوند.\n\nراضی کردنشان به آمدن آسان نبود. بعضی... کدورت‌های قدیمی میان این گروه‌ها هست. Hagar امیدوار از این شکاف‌ها عبور کند.\n\nتا رسیدن بقیه، هر وقت خواستی با نماینده‌های دیگر صحبت کن. انتظار بی‌قرارشان کرده، پس حواست باشد آتش دعوا تند نشود.", o = { "صحبت با نماینده‌ها", "صحبت با Orweyna" }, c = "خوشحالم که دوباره می‌بینمت!\n\n<Kinduru looks around the Den, then sighs.>\n\nمی‌دانی Zul'jan کجای اینجا لگد انداخته رفته؟" }
WoWFQ[92900] = { t = "لطفی به Kinduru", d = "Zul'jarra نمی‌توانست Zul'Aman را ترک کند وقتی Amaniها هنوز دارند نفس تازه می‌کنند. جایش Zul'jan را فرستاد.\n\nامید داشت نشان دادن اعتماد و دادن این مسئولیت به او، بیرونش بیاورد از سایهٔ خودش. از استعدادهایش استفاده شود. اما این خبر...\n\nمن ترول پیری‌ام. کنترل Zul'jan برایم سخت است، اما شاید حرف تو را بشنود.\n\nبه ما می‌پیوندی؟ Zul'jarra و من ممنون می‌شویم اگر Zul'jan دنبال دردسر نگردد.", o = { "کمی بمان و به الف‌ها گوش بده", "کمی بمان و به ترول‌ها گوش بده", "با Zul'jan صحبت کن", "دیدار در Den of Echoes" }, c = "صبرم دارد تمام می‌شود." }
WoWFQ[92901] = { t = "بازنویسی تاریخ", d = "همهٔ رؤیاواه‌های این مکان برایمان روشن نبودند. بعضی‌شان... عجیب بودند.\n\nیکی در خصوصی داشت به مردمی ناآشنا: مردمی که فهمیدیم ترول‌های Amani هستند.\n\nجادویی که برای ساختن نقاشی به کار می‌رود، برای بیرون کشیدن خاطرات از گذشته، به haranirها و نزدیکان‌مان گره خورده است. اگر پیوندی نبود، Zur'asharها--سازندگان نقاشی‌ها--نمی‌توانستند تاریخ ترول‌ها را فرا بخوانند.\n\nمی‌توانم تو و Zul'jan را ببرم، و خودتان داوری کنید.", o = { "فعال کردن visionstone باستانی", "کمک به Amaniها", "تکمیل احضار", "در Den of Echoes با Orweyna صحبت کن." }, c = "تاریخ Amani، نقاشی‌شده بر دیوارهای اجداد ما. این جادو بدون پیوند میان مردم‌مان کار نمی‌کند." }
WoWFQ[93013] = { t = "مأموریت ویژه: پس راندن نور", d = "باید به آسمان بزنیم و Lightbloom را پس برانیم!", o = { "سوار شدن بر Haranir Petalwing", "شکست دادن rutaaniهای Lightbloom" }, c = "خوب بود. با این حال باید مراقب باشیم تا Lightbloom دوباره نپخشد." }
WoWFQ[93053] = { t = "پاک‌بازی Den", d = "چند شیطن‌پیشهٔ مزاحم دور Cradle بلوط ریخته‌اند. جمع‌شان می‌کنی؟", o = { "حذف بلوط خشک" }, c = "حتی کوچک‌ترین موجودات harandar هم طاقت یک لقمهٔ خوب را ندارند. اما پوست تو از دندانشان سخت‌تر بود!" }
WoWFQ[93416] = { t = "فراخوان کاوشگر: The Gulf of Memory", d = "شایعهٔ آشوب در Gulf of Memory پیچیده است. پیش از ریشه دواندن، سر و کلاش بگذار.", o = { "تکمیل delve در The Gulf of Memory در هر سختی", "در Den با Zur'ashar Kassameh صحبت کن." }, p = "چه چیزی پیدا کردی؟", c = "ممنونم، <name>، که در نطفه خفه‌اش کردی." }
WoWFQ[93421] = { t = "فراخوان کاوشگر: The Grudge Pit", d = "<This moldy hanging has been crudely painted over to depict one fungarian hitting another with what looks to be a chair.>\n\nجنگ بزرگ را ببین. بهترین جنگ!\n\nGrudge Pit. حتماً بیا!", o = { "تکمیل delve در The Grudge Pit در هر سختی" }, p = "جنگ چطور بود؟", c = "جنگ خوب بود؟ آره.\n\nبهترین جنگ؟ شاید!" }
WoWFQ[93932] = { t = "برکت افسانه‌ای", d = "Harandar خرد را در هر برگ از تاریخش پنهان کرده، <name>. خوب است خودت دنبال افسانه‌هایش بگردی. حدس می‌زنم چیزی از این دنیا و جای ما در آن یاد بگیری.", o = { "کشف یک افسانه از haranirها." }, p = "...", c = "نمی‌دانم سنگ‌ها چه به تو نشان دادند. امیدوارم روشنگر بوده باشد، <name>. اما یادت باشد: همیشه چیزهای بیشتری برای آموختن هست." }
WoWFQ[94677] = { t = "Rootwarden گم‌شده", d = "همیشه یک چیز این ماجرا من را می‌آزارد، <name>. Rootwarden کجاست؟\n\nRuia وظیفه‌ای مقدس دارد: پاسداری از World Tree و سرزمین اطرافش. باید همین‌جا باشد، کنار مردمش که به او نیاز دارند. پس در روزهای بحران کجا می‌تواند باشد؟ به چه می‌اندیشد؟\n\nمطمئنم اگر شهرش را بگردیم سرنخ‌هایی از مقصدش پیدا می‌کنیم. شاید در همین راه بیشتر از حال درونش بفهمیم.", o = { "پیدا شدن یادداشت‌های Ruia", "دومی بعداً ظاهر می‌شود", "سومی بعداً ظاهر می‌شود" }, p = "Rootwarden باید همین‌جا باشد. باید بفهمیم چه چیزی آن‌قدر فوری بوده که او را از وظیفه‌اش جدا کند.", c = "خبر نگران‌کننده‌ای است. تا الان Lightbloom هیچ haranیری را اثر نزده بود. مگر Rootwarden را آلوده کرده؟ یا این غرورش است که حرف می‌زند؟ همیشه تند و سرسخت بوده، اما...\n\nباید تند حرکت کنیم." }
WoWFQ[97624] = { t = "به جست‌وجوی افسانه‌ها", d = "Harandar خرد را در هر برگ از تاریخش پنهان کرده، <name>. خوب است خودت دنبال افسانه‌هایش بگردی. حدس می‌زنم چیزی از این دنیا و جای ما در آن یاد بگیری.", o = { "کشف یک افسانه از haranirها." }, p = "...", c = "نمی‌دانم سنگ‌ها چه به تو نشان دادند. امیدوارم روشنگر بوده باشد، <name>. اما یادت باشد: همیشه چیزهای بیشتری برای آموختن هست." }
